flow.typescript:
// D35 · Part 1~4 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d35_flow.ts   (합성 목소리 · 장난감 임베딩으로 모델 다운로드 · 인터넷 없이 실행)
//   목소리 → 임베딩 → 문턱(EER · FAR 1%) → 등록(암호화 보관) → 본인 확인 · 1:N 식별 → 위조(복제 · 재생) 방어까지 한 번에
import { createCipheriv, createDecipheriv, createHash, randomBytes } from "node:crypto";
function fft(re: Float64Array, im: Float64Array, inverse: boolean = false): void {
  // 제자리 FFT (길이는 2의 거듭제곱). inverse = true 이면 역변환(1/N 포함)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = ((inverse ? 2 : -2) * Math.PI) / len;
    const wr = Math.cos(ang);
    const wi = Math.sin(ang);
    for (let i = 0; i < n; i += len) {
      let cr = 1;
      let ci = 0;
      for (let k = 0; k < len / 2; k++) {
        const a = i + k;
        const b = a + len / 2;
        const tr = re[b] * cr - im[b] * ci;
        const ti = re[b] * ci + im[b] * cr;
        re[b] = re[a] - tr;
        im[b] = im[a] - ti;
        re[a] += tr;
        im[a] += ti;
        const nr = cr * wr - ci * wi;
        ci = cr * wi + ci * wr;
        cr = nr;
      }
    }
  }
  if (inverse)
    for (let i = 0; i < n; i++) {
      re[i] /= n;
      im[i] /= n;
    }
}

function powerSpectrum(x: ArrayLike<number>, nfft: number): Float64Array {
  // 실수 신호의 파워 스펙트럼(0 ~ 나이퀴스트, nfft/2 + 1칸). 모자라면 0으로 채움
  const re = new Float64Array(nfft);
  const im = new Float64Array(nfft);
  for (let i = 0; i < Math.min(nfft, x.length); i++) re[i] = x[i];
  fft(re, im);
  const p = new Float64Array(nfft / 2 + 1);
  for (let k = 0; k <= nfft / 2; k++) p[k] = re[k] * re[k] + im[k] * im[k];
  return p;
}

const SR = 16000;
const N_SPK = 8; // 화자 8명
const N_UTT = 12; // 화자마다 문장 12개
const N_ENROLL = 3; // 등록에 3개
const BANDS = 24; // 장난감 임베딩의 길이 (진짜 ECAPA는 192, WavLM-SV는 512)
const EDGES = Array.from({ length: BANDS + 1 }, (_, i) => 150 * (7000 / 150) ** (i / BANDS)); // 150 Hz ~ 7 kHz를 로그 간격 24칸으로

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function rngOf(seed: number): { uniform: (a: number, b: number) => number; normal: () => number } {
  const r = mulberry32(seed);
  return { uniform: (a, b) => a + (b - a) * r(), normal: () => Math.sqrt(-2 * Math.log(Math.max(r(), 1e-12))) * Math.cos(2 * Math.PI * r()) };
}

type Spk = [number, number, number, number, number]; // f0 · F1 · F2 · F3 · tilt

function makeSpeakers(n: number = N_SPK, seed: number = 0): Spk[] {
  // 가상의 화자: 목소리 높이(f0) · 입 모양이 만드는 공명(F1 F2 F3) · 고음이 줄어드는 정도(tilt). (대체 경로: Zeroth Korean 대신)
  const r = rngOf(seed);
  return Array.from({ length: n }, () => [r.uniform(95, 260), r.uniform(300, 850), r.uniform(1000, 2300), r.uniform(2500, 3300), r.uniform(0.8, 1.4)] as Spk);
}

function voice(spk: Spk, seed: number, human: boolean = true, sec: number = 1.0): Float32Array {
  // 화자 spk가 문장 seed를 말한 1초 소리(합성). human=false면 TTS 같은 소리: 음높이 · 세기 · 입 모양이 늘 일정하고 잡음도 일정
  const r = rngOf(seed);
  const [f0, f1, f2, f3, tilt] = spk;
  const n = Math.floor(sec * SR);
  const forms = [f1, f2, f3].map((f) => f * (human ? r.uniform(0.95, 1.05) : 1)); // 말할 때마다 입 모양이 조금씩 다름
  const walk = new Float64Array(n + 1); // 걷는 값의 누적합 → 천천히 흔들리는 억양
  for (let i = 0; i < n; i++) walk[i + 1] = walk[i] + r.normal();
  const drift = Float64Array.from({ length: n }, (_, i) => (walk[Math.min(n, i + 1600)] - walk[Math.max(0, i - 1600)]) / 3200);
  const peak = drift.reduce((m, v) => Math.max(m, Math.abs(v)), 0) + 1e-9;
  const phase = new Float64Array(n);
  let acc = 0;
  for (let i = 0; i < n; i++) {
    acc += (2 * Math.PI * f0 * (1 + (human ? 0.12 : 0.04) * (drift[i] / peak))) / SR; // 억양 (TTS는 덜 흔들림)
    phase[i] = acc;
  }
  const y = new Float64Array(n);
  for (let k = 1; k <= Math.floor(7000 / f0); k++) {
    let amp = 0.01 * k ** -tilt;
    [90, 110, 150].forEach((bw, i) => (amp += k ** -tilt * Math.exp(-0.5 * ((k * f0 - forms[i]) / bw) ** 2)));
    for (let i = 0; i < n; i++) y[i] += amp * Math.sin(k * phase[i]);
  }
  if (human) {
    const rate = r.uniform(2, 4);
    const ph = r.uniform(0, 6.28);
    for (let i = 0; i < n; i++) y[i] *= 1 + 0.5 * Math.sin((2 * Math.PI * rate * i) / SR + ph); // 문장마다 다른 음절 세기
  }
  const top = y.reduce((m, v) => Math.max(m, Math.abs(v)), 0);
  const noise = human ? r.uniform(0.01, 0.03) : 0.02; // 숨소리 · 마이크 잡음 (TTS는 늘 같은 크기)
  return Float32Array.from(y, (v) => (0.5 * v) / top + noise * r.normal());
}

function embed(y: Float32Array): Float64Array {
  // 장난감 화자 임베딩: 소리의 평균 스펙트럼을 24칸으로 모아 로그를 취하고 전체 크기(평균)를 뺀다 → 크기와 상관없이 '목소리 모양'만 남음
  const p = new Float64Array(257);
  let frames = 0;
  for (let s = 0; s + 512 <= y.length; s += 256, frames++) {
    const re = new Float64Array(512);
    const im = new Float64Array(512);
    for (let i = 0; i < 512; i++) re[i] = y[s + i] * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / 511)); // 한(Hann) 창
    fft(re, im);
    for (let k = 0; k <= 256; k++) p[k] += re[k] * re[k] + im[k] * im[k];
  }
  const e = new Float64Array(BANDS);
  for (let b = 0; b < BANDS; b++) {
    let sum = 0;
    for (let k = 0; k <= 256; k++) {
      const f = (k * SR) / 512;
      if (f >= EDGES[b] && f < EDGES[b + 1]) sum += p[k] / frames;
    }
    e[b] = Math.log10(sum + 1e-10);
  }
  const mean = e.reduce((a, v) => a + v, 0) / BANDS;
  return e.map((v) => v - mean);
}

const dot = (a: ArrayLike<number>, b: ArrayLike<number>): number => {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * b[i];
  return s;
};
const norm = (a: ArrayLike<number>): number => Math.sqrt(dot(a, a));
const l2n = (e: ArrayLike<number>): Float64Array => Float64Array.from(e as ArrayLike<number>, (v) => v / norm(e)); // 길이(L2 노름)를 1로 → 내적 = 코사인 유사도
const meanVec = (vs: ArrayLike<number>[]): Float64Array => Float64Array.from({ length: vs[0].length }, (_, i) => vs.reduce((a, v) => a + v[i], 0) / vs.length);

function buildData(): [Spk[], Float64Array[][]] {
  // 화자 · 문장마다 소리를 만들고 임베딩 (E[화자][문장] = 길이 1짜리 24개 숫자)
  const spks = makeSpeakers();
  const E = spks.map((s, i) => Array.from({ length: N_UTT }, (_, u) => l2n(embed(voice(s, 1000 * i + u)))));
  return [spks, E];
}

function makeTrials(E: Float64Array[][], nEnroll: number = N_ENROLL): [number[], number[]] {
  // 본인 · 타인 시도 점수: 등록 템플릿 = 등록 문장 임베딩의 평균, 시험 = 나머지 문장
  const T = E.map((rows) => l2n(meanVec(rows.slice(0, nEnroll))));
  const tgt: number[] = [];
  const non: number[] = [];
  E.forEach((rows, s) => {
    for (let u = nEnroll; u < rows.length; u++) T.forEach((t, c) => (c === s ? tgt : non).push(dot(rows[u], t)));
  });
  return [tgt, non];
}

const mean = (a: number[]): number => a.reduce((x, y) => x + y, 0) / a.length;

function farFrr(tgt: number[], non: number[], th: number): [number, number] {
  const far = mean(non.map((v) => (v >= th ? 1 : 0))); // 남을 본인으로 받아들인 비율 → '타인 점수'에서 셈
  const frr = mean(tgt.map((v) => (v < th ? 1 : 0))); // 본인을 거절한 비율
  return [far, frr];
}

function eer(tgt: number[], non: number[]): [number, number] {
  // FAR과 FRR이 같아지는 지점의 오류율(EER)과 그때의 문턱
  const ths = [...tgt, ...non].sort((a, b) => a - b);
  let best = 0;
  let bestGap = Infinity;
  let val = 0;
  for (const t of ths) {
    const [far, frr] = farFrr(tgt, non, t);
    if (Math.abs(far - frr) < bestGap) {
      bestGap = Math.abs(far - frr);
      best = t;
      val = (far + frr) / 2;
    }
  }
  return [val, best];
}

function quantile(a: number[], q: number): number {
  // numpy의 기본(선형 보간) 분위수
  const s = [...a].sort((x, y) => x - y);
  const pos = (s.length - 1) * q;
  const lo = Math.floor(pos);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (pos - lo);
}

const thAtFar = (non: number[], targetFar: number): number => quantile(non, 1 - targetFar); // 타인 점수의 (1 − 목표 FAR) 분위수
const thAtFrr = (tgt: number[], targetFrr: number): number => quantile(tgt, targetFrr); // 본인 점수의 (목표 FRR) 분위수
const pFalseAccept = (far: number, n: number): number => 1 - (1 - far) ** n; // n명과 차례로 비교해 '한 번이라도' 문턱을 넘을 확률 (독립 가정)

class VoiceID {
  embedFn: (y: Float32Array) => Float64Array;
  th: number;
  db: Map<string, Float64Array> = new Map(); // 이름 → 등록 템플릿 (길이 1)
  constructor(embedFn: (y: Float32Array) => Float64Array, threshold: number) {
    this.embedFn = embedFn;
    this.th = threshold;
  }
  enroll(name: string, clips: Float32Array[]): void {
    // 등록: 몇 문장의 임베딩 평균
    this.db.set(name, l2n(meanVec(clips.map((c) => l2n(this.embedFn(c))))));
  }
  verify(name: string, clip: Float32Array): [boolean, number] {
    // 1:1 본인 확인
    const t = this.db.get(name);
    if (!t) throw new Error(`등록되지 않은 사람: ${name}`);
    const s = dot(l2n(this.embedFn(clip)), t);
    return [s >= this.th, s];
  }
  identify(clip: Float32Array): [string, Record<string, number>] {
    // 1:N 누구인가 (+ 모르는 사람 거절)
    const e = l2n(this.embedFn(clip));
    const scores: Record<string, number> = {};
    for (const [n, t] of this.db) scores[n] = dot(e, t);
    const best = Object.keys(scores).reduce((a, b) => (scores[b] > scores[a] ? b : a)); // 점수(값)가 가장 큰 '이름(키)'
    return [scores[best] >= this.th ? best : "모르는 사람", scores];
  }
}

const DCT_COS = Array.from({ length: 20 }, (_, q) => Float64Array.from({ length: 257 }, (_, k) => Math.cos((Math.PI * (2 * k + 1) * q) / 514))); // DCT-II 표 (미리 계산)

function lfcc(y: Float32Array, n: number = 20): Float64Array {
  // 위조 탐지에서 많이 쓰는 특징: 로그 스펙트럼 → 켑스트럼(DCT). 시간에 따른 평균 · 흔들림 · 변화 속도를 이어 60개 숫자로
  const C: Float64Array[] = [];
  for (let s = 0; s + 512 <= y.length; s += 160) {
    const re = new Float64Array(512);
    const im = new Float64Array(512);
    for (let i = 0; i < 512; i++) re[i] = y[s + i] * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / 511));
    fft(re, im);
    const logP = Float64Array.from({ length: 257 }, (_, k) => Math.log(re[k] * re[k] + im[k] * im[k] + 1e-10)); // 멜이 아니라 고르게 257개 주파수
    C.push(Float64Array.from({ length: n }, (_, q) => (q === 0 ? Math.sqrt(1 / 257) : Math.sqrt(2 / 257)) * logP.reduce((a, v, k) => a + v * DCT_COS[q][k], 0))); // 로그 스펙트럼 → 켑스트럼(DCT-II)
  }
  const col = (q: number): number[] => C.map((c) => c[q]);
  const std = (a: number[]): number => Math.sqrt(mean(a.map((v) => (v - mean(a)) ** 2)));
  const diff = (a: number[]): number[] => a.slice(1).map((v, i) => v - a[i]);
  const idx = Array.from({ length: n }, (_, q) => q);
  return Float64Array.from([...idx.map((q) => mean(col(q))), ...idx.map((q) => std(col(q))), ...idx.map((q) => std(diff(col(q))))]);
}

class Detector {
  // 표준화 + 로지스틱 회귀(경사 하강법). 0에 가까우면 진짜 사람, 1에 가까우면 위조
  mu: Float64Array = new Float64Array(0);
  sd: Float64Array = new Float64Array(0);
  w: Float64Array = new Float64Array(0);
  b: number = 0;
  fit(X: Float64Array[], y: number[], l2: number = 0.01, steps: number = 3000, lr: number = 0.3): Detector {
    const d = X[0].length;
    this.mu = Float64Array.from({ length: d }, (_, j) => mean(X.map((r) => r[j])));
    this.sd = Float64Array.from({ length: d }, (_, j) => Math.sqrt(mean(X.map((r) => (r[j] - this.mu[j]) ** 2))) + 1e-9);
    const Z = X.map((r) => r.map((v, j) => (v - this.mu[j]) / this.sd[j]));
    this.w = new Float64Array(d);
    this.b = 0;
    for (let it = 0; it < steps; it++) {
      const gw = new Float64Array(d);
      let gb = 0;
      Z.forEach((z, i) => {
        const err = 1 / (1 + Math.exp(-(dot(z, this.w) + this.b))) - y[i];
        for (let j = 0; j < d; j++) gw[j] += (err * z[j]) / Z.length;
        gb += err / Z.length;
      });
      for (let j = 0; j < d; j++) this.w[j] -= lr * (gw[j] + l2 * this.w[j]);
      this.b -= lr * gb;
    }
    return this;
  }
  score(clip: Float32Array): number {
    const f = lfcc(clip);
    const z = f.map((v, j) => (v - this.mu[j]) / this.sd[j]);
    return 1 / (1 + Math.exp(-(dot(z, this.w) + this.b))); // 위조일 확률
  }
}

// ① 목소리를 숫자로 → 본인 · 타인 점수 → 문턱
const [spks, E] = buildData();
const [tgt, non] = makeTrials(E);
const [e, thEer] = eer(tgt, non);
const TH_SEC = thAtFar(non, 0.01);
const [far, frr] = farFrr(tgt, non, TH_SEC);
console.log(`① 임베딩 ${N_SPK}×${N_UTT}×${BANDS} · EER ${(e * 100).toFixed(2)}% (문턱 ${thEer.toFixed(3)}) · 보안 문턱 ${TH_SEC.toFixed(3)} → FAR ${(far * 100).toFixed(2)}% / FRR ${(frr * 100).toFixed(2)}%`);
check(e < 0.1 && far < 0.03, "EER은 작고, FAR 1% 문턱의 실제 FAR은 3% 아래여야 해요.");

// ② 등록 + 암호화 보관
const FAMILY: Record<string, number> = { 김하늘: 0, 김바다: 1, 이소라: 2 };
const VID = new VoiceID(embed, TH_SEC);
for (const [name, i] of Object.entries(FAMILY)) VID.enroll(name, Array.from({ length: N_ENROLL }, (_, u) => voice(spks[i], 1000 * i + u)));
const key = randomBytes(32);
const aad = createHash("sha256").update("김하늘").digest().subarray(0, 8); // 사용자 번호를 함께 묶어 다른 사람 자리로 옮기면 풀리지 않음
const nonce = randomBytes(12);
const tpl = Buffer.from(new Float32Array(VID.db.get("김하늘") as Float64Array).buffer);
const c = createCipheriv("aes-256-gcm", key, nonce);
c.setAAD(aad);
const sealed = Buffer.concat([nonce, c.update(tpl), c.final(), c.getAuthTag()]);
const d = createDecipheriv("aes-256-gcm", key, sealed.subarray(0, 12));
d.setAAD(aad);
d.setAuthTag(sealed.subarray(sealed.length - 16));
const opened = Buffer.concat([d.update(sealed.subarray(12, sealed.length - 16)), d.final()]);
console.log(`② 등록 ${[...VID.db.keys()]} · 암호화 보관 ${sealed.length}바이트 → 복호화 일치 ${opened.equals(tpl)}`);
check(opened.equals(tpl) && !sealed.includes(tpl), "템플릿은 암호화해 보관하고, 풀면 같아야 해요.");

// ③ 본인 확인 (1:1) · 식별 (1:N)
const [okMe, sMe] = VID.verify("김하늘", voice(spks[0], 1008));
const [okOther, sOther] = VID.verify("김하늘", voice(spks[6], 6008));
const [who] = VID.identify(voice(spks[2], 2009));
const [stranger] = VID.identify(voice(spks[7], 7009));
console.log(`③ 본인 ${sMe.toFixed(3)} ${okMe} · 사칭 ${sOther.toFixed(3)} ${okOther} · 식별 → ${who} · 모르는 사람 → ${stranger}`);
check(okMe && !okOther && who === "이소라" && stranger === "모르는 사람", "본인은 통과, 사칭은 거절, 가족은 식별, 모르는 사람은 거절해야 해요.");

// ④ 위조 방어: 복제 음성은 목소리 · 문장을 통과하지만 위조 탐지가 막는다
const realTrain = spks.flatMap((s, i) => Array.from({ length: 6 }, (_, u) => voice(s, 1000 * i + u)));
const fakeTrain = makeSpeakers(16, 99).flatMap((s, k) => Array.from({ length: 6 }, (_, j) => voice(s, 500 + 6 * k + j, false)));
const DET = new Detector().fit([...realTrain, ...fakeTrain].map((y) => lfcc(y)), [...realTrain.map(() => 0), ...fakeTrain.map(() => 1)]);
const clone = voice(spks[0], 9001, false); // 김하늘 목소리 모양을 따라 한 TTS (대체 경로: 진짜 목소리 복제 모델 대신)
const [okClone, sClone] = VID.verify("김하늘", clone);
const liveMe = DET.score(voice(spks[0], 7001));
const liveClone = DET.score(clone);
console.log(`④ 복제 음성: 화자 점수 ${sClone.toFixed(3)} → 통과 ${okClone} · 위조 점수 ${liveClone.toFixed(2)} (본인 목소리는 ${liveMe.toFixed(2)})`);
check(okClone && liveClone >= 0.5 && liveMe < 0.5, "복제 음성은 화자 검증만으로 통과하지만 위조 탐지가 잡아내요.");

const [challenge, spoken] = ["3-1-4", "9-2-6"]; // 재생 공격: 예전 녹음에 담긴 문장은 오늘 요청한 문장과 다르다
check(spoken !== challenge, "무작위 문장을 요청하면 재생 녹음은 문장이 달라 막혀요.");

space.typescript:
// D35 · Part 1 · 목소리를 숫자로: 임베딩 공간 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d35_space.ts   (합성 목소리 · 장난감 임베딩(24개 숫자)으로 모델 다운로드 · 인터넷 없이 실행)
//   목소리를 숫자로: 화자 8명 · 문장 12개를 장난감 화자 임베딩(24개 숫자, 길이 1)으로 바꾸고, 같은 사람끼리 모이는지 확인
function fft(re: Float64Array, im: Float64Array, inverse: boolean = false): void {
  // 제자리 FFT (길이는 2의 거듭제곱). inverse = true 이면 역변환(1/N 포함)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = ((inverse ? 2 : -2) * Math.PI) / len;
    const wr = Math.cos(ang);
    const wi = Math.sin(ang);
    for (let i = 0; i < n; i += len) {
      let cr = 1;
      let ci = 0;
      for (let k = 0; k < len / 2; k++) {
        const a = i + k;
        const b = a + len / 2;
        const tr = re[b] * cr - im[b] * ci;
        const ti = re[b] * ci + im[b] * cr;
        re[b] = re[a] - tr;
        im[b] = im[a] - ti;
        re[a] += tr;
        im[a] += ti;
        const nr = cr * wr - ci * wi;
        ci = cr * wi + ci * wr;
        cr = nr;
      }
    }
  }
  if (inverse)
    for (let i = 0; i < n; i++) {
      re[i] /= n;
      im[i] /= n;
    }
}

function powerSpectrum(x: ArrayLike<number>, nfft: number): Float64Array {
  // 실수 신호의 파워 스펙트럼(0 ~ 나이퀴스트, nfft/2 + 1칸). 모자라면 0으로 채움
  const re = new Float64Array(nfft);
  const im = new Float64Array(nfft);
  for (let i = 0; i < Math.min(nfft, x.length); i++) re[i] = x[i];
  fft(re, im);
  const p = new Float64Array(nfft / 2 + 1);
  for (let k = 0; k <= nfft / 2; k++) p[k] = re[k] * re[k] + im[k] * im[k];
  return p;
}

const SR = 16000;
const N_SPK = 8; // 화자 8명
const N_UTT = 12; // 화자마다 문장 12개
const N_ENROLL = 3; // 등록에 3개
const BANDS = 24; // 장난감 임베딩의 길이 (진짜 ECAPA는 192, WavLM-SV는 512)
const EDGES = Array.from({ length: BANDS + 1 }, (_, i) => 150 * (7000 / 150) ** (i / BANDS)); // 150 Hz ~ 7 kHz를 로그 간격 24칸으로

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function rngOf(seed: number): { uniform: (a: number, b: number) => number; normal: () => number } {
  const r = mulberry32(seed);
  return { uniform: (a, b) => a + (b - a) * r(), normal: () => Math.sqrt(-2 * Math.log(Math.max(r(), 1e-12))) * Math.cos(2 * Math.PI * r()) };
}

type Spk = [number, number, number, number, number]; // f0 · F1 · F2 · F3 · tilt

function makeSpeakers(n: number = N_SPK, seed: number = 0): Spk[] {
  // 가상의 화자: 목소리 높이(f0) · 입 모양이 만드는 공명(F1 F2 F3) · 고음이 줄어드는 정도(tilt). (대체 경로: Zeroth Korean 대신)
  const r = rngOf(seed);
  return Array.from({ length: n }, () => [r.uniform(95, 260), r.uniform(300, 850), r.uniform(1000, 2300), r.uniform(2500, 3300), r.uniform(0.8, 1.4)] as Spk);
}

function voice(spk: Spk, seed: number, human: boolean = true, sec: number = 1.0): Float32Array {
  // 화자 spk가 문장 seed를 말한 1초 소리(합성). human=false면 TTS 같은 소리: 음높이 · 세기 · 입 모양이 늘 일정하고 잡음도 일정
  const r = rngOf(seed);
  const [f0, f1, f2, f3, tilt] = spk;
  const n = Math.floor(sec * SR);
  const forms = [f1, f2, f3].map((f) => f * (human ? r.uniform(0.95, 1.05) : 1)); // 말할 때마다 입 모양이 조금씩 다름
  const walk = new Float64Array(n + 1); // 걷는 값의 누적합 → 천천히 흔들리는 억양
  for (let i = 0; i < n; i++) walk[i + 1] = walk[i] + r.normal();
  const drift = Float64Array.from({ length: n }, (_, i) => (walk[Math.min(n, i + 1600)] - walk[Math.max(0, i - 1600)]) / 3200);
  const peak = drift.reduce((m, v) => Math.max(m, Math.abs(v)), 0) + 1e-9;
  const phase = new Float64Array(n);
  let acc = 0;
  for (let i = 0; i < n; i++) {
    acc += (2 * Math.PI * f0 * (1 + (human ? 0.12 : 0.04) * (drift[i] / peak))) / SR; // 억양 (TTS는 덜 흔들림)
    phase[i] = acc;
  }
  const y = new Float64Array(n);
  for (let k = 1; k <= Math.floor(7000 / f0); k++) {
    let amp = 0.01 * k ** -tilt;
    [90, 110, 150].forEach((bw, i) => (amp += k ** -tilt * Math.exp(-0.5 * ((k * f0 - forms[i]) / bw) ** 2)));
    for (let i = 0; i < n; i++) y[i] += amp * Math.sin(k * phase[i]);
  }
  if (human) {
    const rate = r.uniform(2, 4);
    const ph = r.uniform(0, 6.28);
    for (let i = 0; i < n; i++) y[i] *= 1 + 0.5 * Math.sin((2 * Math.PI * rate * i) / SR + ph); // 문장마다 다른 음절 세기
  }
  const top = y.reduce((m, v) => Math.max(m, Math.abs(v)), 0);
  const noise = human ? r.uniform(0.01, 0.03) : 0.02; // 숨소리 · 마이크 잡음 (TTS는 늘 같은 크기)
  return Float32Array.from(y, (v) => (0.5 * v) / top + noise * r.normal());
}

function embed(y: Float32Array): Float64Array {
  // 장난감 화자 임베딩: 소리의 평균 스펙트럼을 24칸으로 모아 로그를 취하고 전체 크기(평균)를 뺀다 → 크기와 상관없이 '목소리 모양'만 남음
  const p = new Float64Array(257);
  let frames = 0;
  for (let s = 0; s + 512 <= y.length; s += 256, frames++) {
    const re = new Float64Array(512);
    const im = new Float64Array(512);
    for (let i = 0; i < 512; i++) re[i] = y[s + i] * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / 511)); // 한(Hann) 창
    fft(re, im);
    for (let k = 0; k <= 256; k++) p[k] += re[k] * re[k] + im[k] * im[k];
  }
  const e = new Float64Array(BANDS);
  for (let b = 0; b < BANDS; b++) {
    let sum = 0;
    for (let k = 0; k <= 256; k++) {
      const f = (k * SR) / 512;
      if (f >= EDGES[b] && f < EDGES[b + 1]) sum += p[k] / frames;
    }
    e[b] = Math.log10(sum + 1e-10);
  }
  const mean = e.reduce((a, v) => a + v, 0) / BANDS;
  return e.map((v) => v - mean);
}

const dot = (a: ArrayLike<number>, b: ArrayLike<number>): number => {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * b[i];
  return s;
};
const norm = (a: ArrayLike<number>): number => Math.sqrt(dot(a, a));
const l2n = (e: ArrayLike<number>): Float64Array => Float64Array.from(e as ArrayLike<number>, (v) => v / norm(e)); // 길이(L2 노름)를 1로 → 내적 = 코사인 유사도
const meanVec = (vs: ArrayLike<number>[]): Float64Array => Float64Array.from({ length: vs[0].length }, (_, i) => vs.reduce((a, v) => a + v[i], 0) / vs.length);

function buildData(): [Spk[], Float64Array[][]] {
  // 화자 · 문장마다 소리를 만들고 임베딩 (E[화자][문장] = 길이 1짜리 24개 숫자)
  const spks = makeSpeakers();
  const E = spks.map((s, i) => Array.from({ length: N_UTT }, (_, u) => l2n(embed(voice(s, 1000 * i + u)))));
  return [spks, E];
}

function makeTrials(E: Float64Array[][], nEnroll: number = N_ENROLL): [number[], number[]] {
  // 본인 · 타인 시도 점수: 등록 템플릿 = 등록 문장 임베딩의 평균, 시험 = 나머지 문장
  const T = E.map((rows) => l2n(meanVec(rows.slice(0, nEnroll))));
  const tgt: number[] = [];
  const non: number[] = [];
  E.forEach((rows, s) => {
    for (let u = nEnroll; u < rows.length; u++) T.forEach((t, c) => (c === s ? tgt : non).push(dot(rows[u], t)));
  });
  return [tgt, non];
}

const mean = (a: number[]): number => a.reduce((x, y) => x + y, 0) / a.length;

function farFrr(tgt: number[], non: number[], th: number): [number, number] {
  const far = mean(non.map((v) => (v >= th ? 1 : 0))); // 남을 본인으로 받아들인 비율 → '타인 점수'에서 셈
  const frr = mean(tgt.map((v) => (v < th ? 1 : 0))); // 본인을 거절한 비율
  return [far, frr];
}

function eer(tgt: number[], non: number[]): [number, number] {
  // FAR과 FRR이 같아지는 지점의 오류율(EER)과 그때의 문턱
  const ths = [...tgt, ...non].sort((a, b) => a - b);
  let best = 0;
  let bestGap = Infinity;
  let val = 0;
  for (const t of ths) {
    const [far, frr] = farFrr(tgt, non, t);
    if (Math.abs(far - frr) < bestGap) {
      bestGap = Math.abs(far - frr);
      best = t;
      val = (far + frr) / 2;
    }
  }
  return [val, best];
}

function quantile(a: number[], q: number): number {
  // numpy의 기본(선형 보간) 분위수
  const s = [...a].sort((x, y) => x - y);
  const pos = (s.length - 1) * q;
  const lo = Math.floor(pos);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (pos - lo);
}

const thAtFar = (non: number[], targetFar: number): number => quantile(non, 1 - targetFar); // 타인 점수의 (1 − 목표 FAR) 분위수
const thAtFrr = (tgt: number[], targetFrr: number): number => quantile(tgt, targetFrr); // 본인 점수의 (목표 FRR) 분위수
const pFalseAccept = (far: number, n: number): number => 1 - (1 - far) ** n; // n명과 차례로 비교해 '한 번이라도' 문턱을 넘을 확률 (독립 가정)

class VoiceID {
  embedFn: (y: Float32Array) => Float64Array;
  th: number;
  db: Map<string, Float64Array> = new Map(); // 이름 → 등록 템플릿 (길이 1)
  constructor(embedFn: (y: Float32Array) => Float64Array, threshold: number) {
    this.embedFn = embedFn;
    this.th = threshold;
  }
  enroll(name: string, clips: Float32Array[]): void {
    // 등록: 몇 문장의 임베딩 평균
    this.db.set(name, l2n(meanVec(clips.map((c) => l2n(this.embedFn(c))))));
  }
  verify(name: string, clip: Float32Array): [boolean, number] {
    // 1:1 본인 확인
    const t = this.db.get(name);
    if (!t) throw new Error(`등록되지 않은 사람: ${name}`);
    const s = dot(l2n(this.embedFn(clip)), t);
    return [s >= this.th, s];
  }
  identify(clip: Float32Array): [string, Record<string, number>] {
    // 1:N 누구인가 (+ 모르는 사람 거절)
    const e = l2n(this.embedFn(clip));
    const scores: Record<string, number> = {};
    for (const [n, t] of this.db) scores[n] = dot(e, t);
    const best = Object.keys(scores).reduce((a, b) => (scores[b] > scores[a] ? b : a)); // 점수(값)가 가장 큰 '이름(키)'
    return [scores[best] >= this.th ? best : "모르는 사람", scores];
  }
}

const [spks, E] = buildData(); // E[화자 8][문장 12] = 임베딩 24개 숫자
const y0 = voice(spks[0], 1);
console.log(`소리 ${y0.length.toLocaleString()}샘플 → 임베딩 ${embed(y0).length}개 → 길이 맞춘 뒤 ${norm(E[0][0]).toFixed(4)} · 전체 ${N_SPK}×${N_UTT}×${BANDS}`);
check(embed(y0).length === BANDS && E.flat().every((e) => Math.abs(norm(e) - 1) < 1e-9), "임베딩은 고정 길이 숫자 묶음이고, 길이를 1로 맞춰 둬요.");

// 1) 같은 사람끼리는 닮고(코사인 ↑), 다른 사람끼리는 덜 닮는다
const flat = E.flat();
const spkId = flat.map((_, i) => Math.floor(i / N_UTT));
const same: number[] = [];
const diff: number[] = [];
for (let i = 0; i < flat.length; i++) for (let j = 0; j < flat.length; j++) if (i !== j) (spkId[i] === spkId[j] ? same : diff).push(dot(flat[i], flat[j]));
console.log(`같은 사람 평균 ${mean(same).toFixed(3)} · 다른 사람 평균 ${mean(diff).toFixed(3)}`);
check(mean(same) > mean(diff) + 0.5, "같은 사람 문장 쌍이 훨씬 닮아야 해요.");

// 2) 소리 크기와 상관없는 숫자: 3배 크게 말해도, 1/10로 작게 말해도 같은 임베딩
const a = l2n(embed(y0));
const b = l2n(embed(y0.map((v) => 3 * v)));
const c = l2n(embed(y0.map((v) => 0.1 * v)));
console.log(`크기 3배 → 코사인 ${dot(a, b).toFixed(6)} · 크기 1/10 → 코사인 ${dot(a, c).toFixed(6)}`);
check(dot(a, b) > 0.9999 && dot(a, c) > 0.9999, "임베딩에서 전체 크기(평균)를 빼 두었기 때문에 크기에 흔들리지 않아요.");

// 3) 사람 사이는 멀고 사람 안은 뭉친다 (2차원 대신 임베딩 그대로: 중심까지 거리)
const cent = E.map((rows) => meanVec(rows));
const dist = (u: ArrayLike<number>, v: ArrayLike<number>): number => Math.sqrt(dot(Array.from(u, (x, i) => x - v[i]), Array.from(u, (x, i) => x - v[i])));
const within = mean(E.flatMap((rows, i) => rows.map((r) => dist(r, cent[i]))));
const between = mean(cent.flatMap((u, i) => cent.slice(i + 1).map((v) => dist(u, v))));
console.log(`같은 사람 안의 퍼짐 ${within.toFixed(3)} · 사람 중심 사이 거리 ${between.toFixed(3)} (비 ${(between / within).toFixed(1)})`);
check(between > 2 * within, "사람 사이 거리가 사람 안의 퍼짐보다 훨씬 커야 해요.");

// 4) 가장 가까운 사람 찾기: 등록 3문장 평균과 가장 닮은 사람을 고르면 대부분 맞힌다
const T = E.map((rows) => l2n(meanVec(rows.slice(0, N_ENROLL))));
const hit: boolean[] = [];
E.forEach((rows, i) => {
  for (let u = N_ENROLL; u < N_UTT; u++) {
    const sc = T.map((t) => dot(t, rows[u]));
    hit.push(sc.indexOf(Math.max(...sc)) === i);
  }
});
console.log(`가장 닮은 등록자 맞히기 ${(mean(hit.map(Number)) * 100).toFixed(1)}% (${hit.filter(Boolean).length}/${hit.length})`);
check(mean(hit.map(Number)) > 0.9, "임베딩만으로도 90% 넘게 사람을 가려내야 해요.");

cosine.typescript:
// D35 · Part 1 · 코사인 유사도 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d35_cosine.ts   (합성 목소리 · 장난감 임베딩으로 모델 다운로드 · 인터넷 없이 실행)
//   코사인 유사도를 처음부터: 길이를 맞추지 않은 두 임베딩 u, v → 방향이 얼마나 같은가(-1 ~ 1). 크기가 달라도 같다
function fft(re: Float64Array, im: Float64Array, inverse: boolean = false): void {
  // 제자리 FFT (길이는 2의 거듭제곱). inverse = true 이면 역변환(1/N 포함)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = ((inverse ? 2 : -2) * Math.PI) / len;
    const wr = Math.cos(ang);
    const wi = Math.sin(ang);
    for (let i = 0; i < n; i += len) {
      let cr = 1;
      let ci = 0;
      for (let k = 0; k < len / 2; k++) {
        const a = i + k;
        const b = a + len / 2;
        const tr = re[b] * cr - im[b] * ci;
        const ti = re[b] * ci + im[b] * cr;
        re[b] = re[a] - tr;
        im[b] = im[a] - ti;
        re[a] += tr;
        im[a] += ti;
        const nr = cr * wr - ci * wi;
        ci = cr * wi + ci * wr;
        cr = nr;
      }
    }
  }
  if (inverse)
    for (let i = 0; i < n; i++) {
      re[i] /= n;
      im[i] /= n;
    }
}

function powerSpectrum(x: ArrayLike<number>, nfft: number): Float64Array {
  // 실수 신호의 파워 스펙트럼(0 ~ 나이퀴스트, nfft/2 + 1칸). 모자라면 0으로 채움
  const re = new Float64Array(nfft);
  const im = new Float64Array(nfft);
  for (let i = 0; i < Math.min(nfft, x.length); i++) re[i] = x[i];
  fft(re, im);
  const p = new Float64Array(nfft / 2 + 1);
  for (let k = 0; k <= nfft / 2; k++) p[k] = re[k] * re[k] + im[k] * im[k];
  return p;
}

const SR = 16000;
const N_SPK = 8; // 화자 8명
const N_UTT = 12; // 화자마다 문장 12개
const N_ENROLL = 3; // 등록에 3개
const BANDS = 24; // 장난감 임베딩의 길이 (진짜 ECAPA는 192, WavLM-SV는 512)
const EDGES = Array.from({ length: BANDS + 1 }, (_, i) => 150 * (7000 / 150) ** (i / BANDS)); // 150 Hz ~ 7 kHz를 로그 간격 24칸으로

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function rngOf(seed: number): { uniform: (a: number, b: number) => number; normal: () => number } {
  const r = mulberry32(seed);
  return { uniform: (a, b) => a + (b - a) * r(), normal: () => Math.sqrt(-2 * Math.log(Math.max(r(), 1e-12))) * Math.cos(2 * Math.PI * r()) };
}

type Spk = [number, number, number, number, number]; // f0 · F1 · F2 · F3 · tilt

function makeSpeakers(n: number = N_SPK, seed: number = 0): Spk[] {
  // 가상의 화자: 목소리 높이(f0) · 입 모양이 만드는 공명(F1 F2 F3) · 고음이 줄어드는 정도(tilt). (대체 경로: Zeroth Korean 대신)
  const r = rngOf(seed);
  return Array.from({ length: n }, () => [r.uniform(95, 260), r.uniform(300, 850), r.uniform(1000, 2300), r.uniform(2500, 3300), r.uniform(0.8, 1.4)] as Spk);
}

function voice(spk: Spk, seed: number, human: boolean = true, sec: number = 1.0): Float32Array {
  // 화자 spk가 문장 seed를 말한 1초 소리(합성). human=false면 TTS 같은 소리: 음높이 · 세기 · 입 모양이 늘 일정하고 잡음도 일정
  const r = rngOf(seed);
  const [f0, f1, f2, f3, tilt] = spk;
  const n = Math.floor(sec * SR);
  const forms = [f1, f2, f3].map((f) => f * (human ? r.uniform(0.95, 1.05) : 1)); // 말할 때마다 입 모양이 조금씩 다름
  const walk = new Float64Array(n + 1); // 걷는 값의 누적합 → 천천히 흔들리는 억양
  for (let i = 0; i < n; i++) walk[i + 1] = walk[i] + r.normal();
  const drift = Float64Array.from({ length: n }, (_, i) => (walk[Math.min(n, i + 1600)] - walk[Math.max(0, i - 1600)]) / 3200);
  const peak = drift.reduce((m, v) => Math.max(m, Math.abs(v)), 0) + 1e-9;
  const phase = new Float64Array(n);
  let acc = 0;
  for (let i = 0; i < n; i++) {
    acc += (2 * Math.PI * f0 * (1 + (human ? 0.12 : 0.04) * (drift[i] / peak))) / SR; // 억양 (TTS는 덜 흔들림)
    phase[i] = acc;
  }
  const y = new Float64Array(n);
  for (let k = 1; k <= Math.floor(7000 / f0); k++) {
    let amp = 0.01 * k ** -tilt;
    [90, 110, 150].forEach((bw, i) => (amp += k ** -tilt * Math.exp(-0.5 * ((k * f0 - forms[i]) / bw) ** 2)));
    for (let i = 0; i < n; i++) y[i] += amp * Math.sin(k * phase[i]);
  }
  if (human) {
    const rate = r.uniform(2, 4);
    const ph = r.uniform(0, 6.28);
    for (let i = 0; i < n; i++) y[i] *= 1 + 0.5 * Math.sin((2 * Math.PI * rate * i) / SR + ph); // 문장마다 다른 음절 세기
  }
  const top = y.reduce((m, v) => Math.max(m, Math.abs(v)), 0);
  const noise = human ? r.uniform(0.01, 0.03) : 0.02; // 숨소리 · 마이크 잡음 (TTS는 늘 같은 크기)
  return Float32Array.from(y, (v) => (0.5 * v) / top + noise * r.normal());
}

function embed(y: Float32Array): Float64Array {
  // 장난감 화자 임베딩: 소리의 평균 스펙트럼을 24칸으로 모아 로그를 취하고 전체 크기(평균)를 뺀다 → 크기와 상관없이 '목소리 모양'만 남음
  const p = new Float64Array(257);
  let frames = 0;
  for (let s = 0; s + 512 <= y.length; s += 256, frames++) {
    const re = new Float64Array(512);
    const im = new Float64Array(512);
    for (let i = 0; i < 512; i++) re[i] = y[s + i] * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / 511)); // 한(Hann) 창
    fft(re, im);
    for (let k = 0; k <= 256; k++) p[k] += re[k] * re[k] + im[k] * im[k];
  }
  const e = new Float64Array(BANDS);
  for (let b = 0; b < BANDS; b++) {
    let sum = 0;
    for (let k = 0; k <= 256; k++) {
      const f = (k * SR) / 512;
      if (f >= EDGES[b] && f < EDGES[b + 1]) sum += p[k] / frames;
    }
    e[b] = Math.log10(sum + 1e-10);
  }
  const mean = e.reduce((a, v) => a + v, 0) / BANDS;
  return e.map((v) => v - mean);
}

const dot = (a: ArrayLike<number>, b: ArrayLike<number>): number => {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * b[i];
  return s;
};
const norm = (a: ArrayLike<number>): number => Math.sqrt(dot(a, a));
const l2n = (e: ArrayLike<number>): Float64Array => Float64Array.from(e as ArrayLike<number>, (v) => v / norm(e)); // 길이(L2 노름)를 1로 → 내적 = 코사인 유사도
const meanVec = (vs: ArrayLike<number>[]): Float64Array => Float64Array.from({ length: vs[0].length }, (_, i) => vs.reduce((a, v) => a + v[i], 0) / vs.length);

function buildData(): [Spk[], Float64Array[][]] {
  // 화자 · 문장마다 소리를 만들고 임베딩 (E[화자][문장] = 길이 1짜리 24개 숫자)
  const spks = makeSpeakers();
  const E = spks.map((s, i) => Array.from({ length: N_UTT }, (_, u) => l2n(embed(voice(s, 1000 * i + u)))));
  return [spks, E];
}

function makeTrials(E: Float64Array[][], nEnroll: number = N_ENROLL): [number[], number[]] {
  // 본인 · 타인 시도 점수: 등록 템플릿 = 등록 문장 임베딩의 평균, 시험 = 나머지 문장
  const T = E.map((rows) => l2n(meanVec(rows.slice(0, nEnroll))));
  const tgt: number[] = [];
  const non: number[] = [];
  E.forEach((rows, s) => {
    for (let u = nEnroll; u < rows.length; u++) T.forEach((t, c) => (c === s ? tgt : non).push(dot(rows[u], t)));
  });
  return [tgt, non];
}

const mean = (a: number[]): number => a.reduce((x, y) => x + y, 0) / a.length;

function farFrr(tgt: number[], non: number[], th: number): [number, number] {
  const far = mean(non.map((v) => (v >= th ? 1 : 0))); // 남을 본인으로 받아들인 비율 → '타인 점수'에서 셈
  const frr = mean(tgt.map((v) => (v < th ? 1 : 0))); // 본인을 거절한 비율
  return [far, frr];
}

function eer(tgt: number[], non: number[]): [number, number] {
  // FAR과 FRR이 같아지는 지점의 오류율(EER)과 그때의 문턱
  const ths = [...tgt, ...non].sort((a, b) => a - b);
  let best = 0;
  let bestGap = Infinity;
  let val = 0;
  for (const t of ths) {
    const [far, frr] = farFrr(tgt, non, t);
    if (Math.abs(far - frr) < bestGap) {
      bestGap = Math.abs(far - frr);
      best = t;
      val = (far + frr) / 2;
    }
  }
  return [val, best];
}

function quantile(a: number[], q: number): number {
  // numpy의 기본(선형 보간) 분위수
  const s = [...a].sort((x, y) => x - y);
  const pos = (s.length - 1) * q;
  const lo = Math.floor(pos);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (pos - lo);
}

const thAtFar = (non: number[], targetFar: number): number => quantile(non, 1 - targetFar); // 타인 점수의 (1 − 목표 FAR) 분위수
const thAtFrr = (tgt: number[], targetFrr: number): number => quantile(tgt, targetFrr); // 본인 점수의 (목표 FRR) 분위수
const pFalseAccept = (far: number, n: number): number => 1 - (1 - far) ** n; // n명과 차례로 비교해 '한 번이라도' 문턱을 넘을 확률 (독립 가정)

class VoiceID {
  embedFn: (y: Float32Array) => Float64Array;
  th: number;
  db: Map<string, Float64Array> = new Map(); // 이름 → 등록 템플릿 (길이 1)
  constructor(embedFn: (y: Float32Array) => Float64Array, threshold: number) {
    this.embedFn = embedFn;
    this.th = threshold;
  }
  enroll(name: string, clips: Float32Array[]): void {
    // 등록: 몇 문장의 임베딩 평균
    this.db.set(name, l2n(meanVec(clips.map((c) => l2n(this.embedFn(c))))));
  }
  verify(name: string, clip: Float32Array): [boolean, number] {
    // 1:1 본인 확인
    const t = this.db.get(name);
    if (!t) throw new Error(`등록되지 않은 사람: ${name}`);
    const s = dot(l2n(this.embedFn(clip)), t);
    return [s >= this.th, s];
  }
  identify(clip: Float32Array): [string, Record<string, number>] {
    // 1:N 누구인가 (+ 모르는 사람 거절)
    const e = l2n(this.embedFn(clip));
    const scores: Record<string, number> = {};
    for (const [n, t] of this.db) scores[n] = dot(e, t);
    const best = Object.keys(scores).reduce((a, b) => (scores[b] > scores[a] ? b : a)); // 점수(값)가 가장 큰 '이름(키)'
    return [scores[best] >= this.th ? best : "모르는 사람", scores];
  }
}

function myCosine(u: ArrayLike<number>, v: ArrayLike<number>): number {
  // cos = (u · v) / (|u| |v|): 두 벡터 사이 각도의 코사인
  return dot(u, v) / (norm(u) * norm(v));
}

const [spks, E] = buildData();
const [ru, rv, rw] = [[0, 1], [0, 2], [1, 3]].map(([i, s]) => embed(voice(spks[i], s))); // 정규화 전 임베딩: 같은 사람 2개 · 다른 사람 1개
const scale = (x: Float64Array, k: number): Float64Array => x.map((v) => k * v);
console.log(`같은 사람 ${myCosine(ru, rv).toFixed(3)} · 다른 사람 ${myCosine(ru, rw).toFixed(3)} · 3배 크게 말해도 ${myCosine(ru, scale(rv, 3)).toFixed(3)} (그대로)`);
const want = [dot(l2n(ru), l2n(rv)), dot(l2n(ru), l2n(rw)), dot(l2n(ru), l2n(rv)), 1.0];
const got = [myCosine(ru, rv), myCosine(ru, rw), myCosine(ru, scale(rv, 3)), myCosine(ru, ru)];
check(got.every((g, i) => Math.abs(g - want[i]) < 1e-9), "길이를 맞춘 뒤 내적한 값과 같아야 해요.");

// 성질 확인: 범위 · 같은 방향 · 직각 · 반대 방향
check(Math.abs(myCosine([1, 2, 3], [2, 4, 6]) - 1) < 1e-12 && Math.abs(myCosine([1, 0], [0, 5])) < 1e-12 && Math.abs(myCosine([1, 2], [-1, -2]) + 1) < 1e-12, "같은 방향은 1, 직각은 0, 반대 방향은 -1이에요.");
check(E.every((rows) => myCosine(ru, rows[0]) >= -1 && myCosine(ru, rows[0]) <= 1), "코사인은 늘 -1 ~ 1 사이예요.");

// 유클리드 거리와 비교: 크기가 달라지면 거리는 변하지만 코사인은 변하지 않는다
const eu = (a: Float64Array, b: Float64Array): number => Math.sqrt(a.reduce((s, v, i) => s + (v - b[i]) ** 2, 0));
const d1 = eu(ru, rv);
const d2 = eu(ru, scale(rv, 3));
console.log(`거리: v일 때 ${d1.toFixed(2)} → 3v일 때 ${d2.toFixed(2)} (변함) · 코사인: ${myCosine(ru, rv).toFixed(3)} → ${myCosine(ru, scale(rv, 3)).toFixed(3)} (그대로)`);
check(Math.abs(d1 - d2) > 1 && Math.abs(myCosine(ru, rv) - myCosine(ru, scale(rv, 3))) < 1e-12, "목소리 크기가 아니라 '모양'을 비교하려고 코사인을 써요.");

// 길이를 1로 맞춰 두면 내적 하나가 코사인: 한꺼번에 계산하기 (행렬 곱)
const T = E.map((rows) => l2n(meanVec(rows.slice(0, N_ENROLL))));
const S = E.map((rows) => T.map((t) => dot(rows[N_ENROLL], t))); // 화자 8명의 시험 문장 × 등록 템플릿 8개
const diag = mean(S.map((r, i) => r[i]));
const off = mean(S.flatMap((r, i) => r.filter((_, j) => j !== i)));
console.log("대각선(본인) 평균", diag.toFixed(3), "· 대각선 밖(타인) 평균", off.toFixed(3));
check(diag > 0.8 && Math.abs(S[2][5] - myCosine(E[2][N_ENROLL], T[5])) < 1e-9, "행렬 곱의 칸 하나가 코사인 하나예요.");

eer.typescript:
// D35 · Part 2 · FAR · FRR · EER — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d35_eer.ts   (합성 목소리 · 장난감 임베딩으로 모델 다운로드 · 인터넷 없이 실행)
//   FAR(남을 받아들인 비율) · FRR(본인을 거절한 비율) · EER(둘이 같아지는 지점): 본인 시도와 타인 시도 점수에서 직접 계산하고 다른 방법으로 검산
function fft(re: Float64Array, im: Float64Array, inverse: boolean = false): void {
  // 제자리 FFT (길이는 2의 거듭제곱). inverse = true 이면 역변환(1/N 포함)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = ((inverse ? 2 : -2) * Math.PI) / len;
    const wr = Math.cos(ang);
    const wi = Math.sin(ang);
    for (let i = 0; i < n; i += len) {
      let cr = 1;
      let ci = 0;
      for (let k = 0; k < len / 2; k++) {
        const a = i + k;
        const b = a + len / 2;
        const tr = re[b] * cr - im[b] * ci;
        const ti = re[b] * ci + im[b] * cr;
        re[b] = re[a] - tr;
        im[b] = im[a] - ti;
        re[a] += tr;
        im[a] += ti;
        const nr = cr * wr - ci * wi;
        ci = cr * wi + ci * wr;
        cr = nr;
      }
    }
  }
  if (inverse)
    for (let i = 0; i < n; i++) {
      re[i] /= n;
      im[i] /= n;
    }
}

function powerSpectrum(x: ArrayLike<number>, nfft: number): Float64Array {
  // 실수 신호의 파워 스펙트럼(0 ~ 나이퀴스트, nfft/2 + 1칸). 모자라면 0으로 채움
  const re = new Float64Array(nfft);
  const im = new Float64Array(nfft);
  for (let i = 0; i < Math.min(nfft, x.length); i++) re[i] = x[i];
  fft(re, im);
  const p = new Float64Array(nfft / 2 + 1);
  for (let k = 0; k <= nfft / 2; k++) p[k] = re[k] * re[k] + im[k] * im[k];
  return p;
}

const SR = 16000;
const N_SPK = 8; // 화자 8명
const N_UTT = 12; // 화자마다 문장 12개
const N_ENROLL = 3; // 등록에 3개
const BANDS = 24; // 장난감 임베딩의 길이 (진짜 ECAPA는 192, WavLM-SV는 512)
const EDGES = Array.from({ length: BANDS + 1 }, (_, i) => 150 * (7000 / 150) ** (i / BANDS)); // 150 Hz ~ 7 kHz를 로그 간격 24칸으로

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function rngOf(seed: number): { uniform: (a: number, b: number) => number; normal: () => number } {
  const r = mulberry32(seed);
  return { uniform: (a, b) => a + (b - a) * r(), normal: () => Math.sqrt(-2 * Math.log(Math.max(r(), 1e-12))) * Math.cos(2 * Math.PI * r()) };
}

type Spk = [number, number, number, number, number]; // f0 · F1 · F2 · F3 · tilt

function makeSpeakers(n: number = N_SPK, seed: number = 0): Spk[] {
  // 가상의 화자: 목소리 높이(f0) · 입 모양이 만드는 공명(F1 F2 F3) · 고음이 줄어드는 정도(tilt). (대체 경로: Zeroth Korean 대신)
  const r = rngOf(seed);
  return Array.from({ length: n }, () => [r.uniform(95, 260), r.uniform(300, 850), r.uniform(1000, 2300), r.uniform(2500, 3300), r.uniform(0.8, 1.4)] as Spk);
}

function voice(spk: Spk, seed: number, human: boolean = true, sec: number = 1.0): Float32Array {
  // 화자 spk가 문장 seed를 말한 1초 소리(합성). human=false면 TTS 같은 소리: 음높이 · 세기 · 입 모양이 늘 일정하고 잡음도 일정
  const r = rngOf(seed);
  const [f0, f1, f2, f3, tilt] = spk;
  const n = Math.floor(sec * SR);
  const forms = [f1, f2, f3].map((f) => f * (human ? r.uniform(0.95, 1.05) : 1)); // 말할 때마다 입 모양이 조금씩 다름
  const walk = new Float64Array(n + 1); // 걷는 값의 누적합 → 천천히 흔들리는 억양
  for (let i = 0; i < n; i++) walk[i + 1] = walk[i] + r.normal();
  const drift = Float64Array.from({ length: n }, (_, i) => (walk[Math.min(n, i + 1600)] - walk[Math.max(0, i - 1600)]) / 3200);
  const peak = drift.reduce((m, v) => Math.max(m, Math.abs(v)), 0) + 1e-9;
  const phase = new Float64Array(n);
  let acc = 0;
  for (let i = 0; i < n; i++) {
    acc += (2 * Math.PI * f0 * (1 + (human ? 0.12 : 0.04) * (drift[i] / peak))) / SR; // 억양 (TTS는 덜 흔들림)
    phase[i] = acc;
  }
  const y = new Float64Array(n);
  for (let k = 1; k <= Math.floor(7000 / f0); k++) {
    let amp = 0.01 * k ** -tilt;
    [90, 110, 150].forEach((bw, i) => (amp += k ** -tilt * Math.exp(-0.5 * ((k * f0 - forms[i]) / bw) ** 2)));
    for (let i = 0; i < n; i++) y[i] += amp * Math.sin(k * phase[i]);
  }
  if (human) {
    const rate = r.uniform(2, 4);
    const ph = r.uniform(0, 6.28);
    for (let i = 0; i < n; i++) y[i] *= 1 + 0.5 * Math.sin((2 * Math.PI * rate * i) / SR + ph); // 문장마다 다른 음절 세기
  }
  const top = y.reduce((m, v) => Math.max(m, Math.abs(v)), 0);
  const noise = human ? r.uniform(0.01, 0.03) : 0.02; // 숨소리 · 마이크 잡음 (TTS는 늘 같은 크기)
  return Float32Array.from(y, (v) => (0.5 * v) / top + noise * r.normal());
}

function embed(y: Float32Array): Float64Array {
  // 장난감 화자 임베딩: 소리의 평균 스펙트럼을 24칸으로 모아 로그를 취하고 전체 크기(평균)를 뺀다 → 크기와 상관없이 '목소리 모양'만 남음
  const p = new Float64Array(257);
  let frames = 0;
  for (let s = 0; s + 512 <= y.length; s += 256, frames++) {
    const re = new Float64Array(512);
    const im = new Float64Array(512);
    for (let i = 0; i < 512; i++) re[i] = y[s + i] * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / 511)); // 한(Hann) 창
    fft(re, im);
    for (let k = 0; k <= 256; k++) p[k] += re[k] * re[k] + im[k] * im[k];
  }
  const e = new Float64Array(BANDS);
  for (let b = 0; b < BANDS; b++) {
    let sum = 0;
    for (let k = 0; k <= 256; k++) {
      const f = (k * SR) / 512;
      if (f >= EDGES[b] && f < EDGES[b + 1]) sum += p[k] / frames;
    }
    e[b] = Math.log10(sum + 1e-10);
  }
  const mean = e.reduce((a, v) => a + v, 0) / BANDS;
  return e.map((v) => v - mean);
}

const dot = (a: ArrayLike<number>, b: ArrayLike<number>): number => {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * b[i];
  return s;
};
const norm = (a: ArrayLike<number>): number => Math.sqrt(dot(a, a));
const l2n = (e: ArrayLike<number>): Float64Array => Float64Array.from(e as ArrayLike<number>, (v) => v / norm(e)); // 길이(L2 노름)를 1로 → 내적 = 코사인 유사도
const meanVec = (vs: ArrayLike<number>[]): Float64Array => Float64Array.from({ length: vs[0].length }, (_, i) => vs.reduce((a, v) => a + v[i], 0) / vs.length);

function buildData(): [Spk[], Float64Array[][]] {
  // 화자 · 문장마다 소리를 만들고 임베딩 (E[화자][문장] = 길이 1짜리 24개 숫자)
  const spks = makeSpeakers();
  const E = spks.map((s, i) => Array.from({ length: N_UTT }, (_, u) => l2n(embed(voice(s, 1000 * i + u)))));
  return [spks, E];
}

function makeTrials(E: Float64Array[][], nEnroll: number = N_ENROLL): [number[], number[]] {
  // 본인 · 타인 시도 점수: 등록 템플릿 = 등록 문장 임베딩의 평균, 시험 = 나머지 문장
  const T = E.map((rows) => l2n(meanVec(rows.slice(0, nEnroll))));
  const tgt: number[] = [];
  const non: number[] = [];
  E.forEach((rows, s) => {
    for (let u = nEnroll; u < rows.length; u++) T.forEach((t, c) => (c === s ? tgt : non).push(dot(rows[u], t)));
  });
  return [tgt, non];
}

const mean = (a: number[]): number => a.reduce((x, y) => x + y, 0) / a.length;

function farFrr(tgt: number[], non: number[], th: number): [number, number] {
  const far = mean(non.map((v) => (v >= th ? 1 : 0))); // 남을 본인으로 받아들인 비율 → '타인 점수'에서 셈
  const frr = mean(tgt.map((v) => (v < th ? 1 : 0))); // 본인을 거절한 비율
  return [far, frr];
}

function eer(tgt: number[], non: number[]): [number, number] {
  // FAR과 FRR이 같아지는 지점의 오류율(EER)과 그때의 문턱
  const ths = [...tgt, ...non].sort((a, b) => a - b);
  let best = 0;
  let bestGap = Infinity;
  let val = 0;
  for (const t of ths) {
    const [far, frr] = farFrr(tgt, non, t);
    if (Math.abs(far - frr) < bestGap) {
      bestGap = Math.abs(far - frr);
      best = t;
      val = (far + frr) / 2;
    }
  }
  return [val, best];
}

function quantile(a: number[], q: number): number {
  // numpy의 기본(선형 보간) 분위수
  const s = [...a].sort((x, y) => x - y);
  const pos = (s.length - 1) * q;
  const lo = Math.floor(pos);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (pos - lo);
}

const thAtFar = (non: number[], targetFar: number): number => quantile(non, 1 - targetFar); // 타인 점수의 (1 − 목표 FAR) 분위수
const thAtFrr = (tgt: number[], targetFrr: number): number => quantile(tgt, targetFrr); // 본인 점수의 (목표 FRR) 분위수
const pFalseAccept = (far: number, n: number): number => 1 - (1 - far) ** n; // n명과 차례로 비교해 '한 번이라도' 문턱을 넘을 확률 (독립 가정)

class VoiceID {
  embedFn: (y: Float32Array) => Float64Array;
  th: number;
  db: Map<string, Float64Array> = new Map(); // 이름 → 등록 템플릿 (길이 1)
  constructor(embedFn: (y: Float32Array) => Float64Array, threshold: number) {
    this.embedFn = embedFn;
    this.th = threshold;
  }
  enroll(name: string, clips: Float32Array[]): void {
    // 등록: 몇 문장의 임베딩 평균
    this.db.set(name, l2n(meanVec(clips.map((c) => l2n(this.embedFn(c))))));
  }
  verify(name: string, clip: Float32Array): [boolean, number] {
    // 1:1 본인 확인
    const t = this.db.get(name);
    if (!t) throw new Error(`등록되지 않은 사람: ${name}`);
    const s = dot(l2n(this.embedFn(clip)), t);
    return [s >= this.th, s];
  }
  identify(clip: Float32Array): [string, Record<string, number>] {
    // 1:N 누구인가 (+ 모르는 사람 거절)
    const e = l2n(this.embedFn(clip));
    const scores: Record<string, number> = {};
    for (const [n, t] of this.db) scores[n] = dot(e, t);
    const best = Object.keys(scores).reduce((a, b) => (scores[b] > scores[a] ? b : a)); // 점수(값)가 가장 큰 '이름(키)'
    return [scores[best] >= this.th ? best : "모르는 사람", scores];
  }
}

const [, E] = buildData();
const [tgt, non] = makeTrials(E);
console.log(`본인 시도 ${tgt.length}번 (평균 ${mean(tgt).toFixed(3)}) · 타인 시도 ${non.length}번 (평균 ${mean(non).toFixed(3)})`);
check(tgt.length === N_SPK * (N_UTT - N_ENROLL) && non.length === tgt.length * (N_SPK - 1) && mean(tgt) > mean(non) + 0.5, "본인 점수가 타인 점수보다 훨씬 높아야 해요.");

// 1) 문턱을 움직이면: 높일수록 남은 덜 받아들이고(FAR ↓) 본인도 더 거절한다(FRR ↑)
const ths = Array.from({ length: 13 }, (_, i) => -0.2 + i * 0.1);
const curve = ths.map((t) => farFrr(tgt, non, t));
ths.forEach((t, i) => {
  if (i % 3 === 0) console.log(`문턱 ${t.toFixed(2).padStart(5)} → FAR ${(curve[i][0] * 100).toFixed(2).padStart(6)}% · FRR ${(curve[i][1] * 100).toFixed(2).padStart(6)}%`);
});
check(curve.every((c, i) => i === 0 || (c[0] <= curve[i - 1][0] + 1e-12 && c[1] >= curve[i - 1][1] - 1e-12)), "문턱이 높아지면 FAR은 줄고 FRR은 늘어요.");
check(farFrr(tgt, non, -1).join() === "1,0" && farFrr(tgt, non, 2).join() === "0,1", "문턱이 아주 낮으면 다 통과(FAR 100%), 아주 높으면 다 거절(FRR 100%)이에요.");

// 2) EER: FAR과 FRR의 차이가 가장 작은 곳
const [e, th] = eer(tgt, non);
const [far, frr] = farFrr(tgt, non, th);
console.log(`EER ${(e * 100).toFixed(2)}% (문턱 ${th.toFixed(3)}) · 그 문턱의 FAR ${(far * 100).toFixed(2)}% / FRR ${(frr * 100).toFixed(2)}%`);
check(Math.abs(far - frr) < 0.05 && e < 0.1, "EER 지점에서는 FAR과 FRR이 거의 같고, 작을수록 좋은 시스템이에요.");

// 3) 검산: 점수를 큰 순서로 세워 문턱을 내려가며 누적(ROC)으로 따로 계산
function eerRoc(tgt: number[], non: number[]): number {
  const all = [...tgt.map((s) => [s, 1]), ...non.map((s) => [s, 0])].sort((x, y) => y[0] - x[0]);
  let tp = 0;
  let fp = 0;
  let best = Infinity;
  let val = 0;
  for (const [, isTgt] of all) {
    if (isTgt) tp++;
    else fp++; // 문턱을 내릴수록 본인도 타인도 더 통과
    const frrNow = 1 - tp / tgt.length;
    const farNow = fp / non.length;
    if (Math.abs(frrNow - farNow) < best) {
      best = Math.abs(frrNow - farNow);
      val = (frrNow + farNow) / 2;
    }
  }
  return val;
}
const ref = eerRoc(tgt, non);
console.log(`EER 검산(ROC 누적) ${(ref * 100).toFixed(2)}%`);
check(Math.abs(ref - e) < 0.02, "두 방법의 EER이 거의 같아야 해요.");

// 4) 점수가 겹치지 않으면 EER 0, 완전히 같으면 50%
check(eer([0.9, 0.8, 0.95], [0.1, 0.2, 0.3])[0] === 0, "분포가 겹치지 않으면 EER은 0이에요.");
const r = rngOf(0);
const sameDist = Array.from({ length: 2000 }, () => 0.5 + 0.1 * r.normal());
const eSame = eer(sameDist.slice(0, 1000), sameDist.slice(1000))[0];
console.log(`본인 · 타인 점수가 같은 분포일 때 EER ${(eSame * 100).toFixed(1)}%`);
check(Math.abs(eSame - 0.5) < 0.05, "구별 못 하는 시스템의 EER은 약 50%예요.");

oppoint.typescript:
// D35 · Part 2 · 운영 문턱 정하기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d35_oppoint.ts   (합성 목소리 · 장난감 임베딩으로 모델 다운로드 · 인터넷 없이 실행)
//   운영 문턱 정하기: '남을 몇 % 허용할까'(FAR)나 '본인을 몇 % 거절할까'(FRR)에서 거꾸로 문턱을 찾고, 등록 인원이 늘 때의 위험을 계산
function fft(re: Float64Array, im: Float64Array, inverse: boolean = false): void {
  // 제자리 FFT (길이는 2의 거듭제곱). inverse = true 이면 역변환(1/N 포함)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = ((inverse ? 2 : -2) * Math.PI) / len;
    const wr = Math.cos(ang);
    const wi = Math.sin(ang);
    for (let i = 0; i < n; i += len) {
      let cr = 1;
      let ci = 0;
      for (let k = 0; k < len / 2; k++) {
        const a = i + k;
        const b = a + len / 2;
        const tr = re[b] * cr - im[b] * ci;
        const ti = re[b] * ci + im[b] * cr;
        re[b] = re[a] - tr;
        im[b] = im[a] - ti;
        re[a] += tr;
        im[a] += ti;
        const nr = cr * wr - ci * wi;
        ci = cr * wi + ci * wr;
        cr = nr;
      }
    }
  }
  if (inverse)
    for (let i = 0; i < n; i++) {
      re[i] /= n;
      im[i] /= n;
    }
}

function powerSpectrum(x: ArrayLike<number>, nfft: number): Float64Array {
  // 실수 신호의 파워 스펙트럼(0 ~ 나이퀴스트, nfft/2 + 1칸). 모자라면 0으로 채움
  const re = new Float64Array(nfft);
  const im = new Float64Array(nfft);
  for (let i = 0; i < Math.min(nfft, x.length); i++) re[i] = x[i];
  fft(re, im);
  const p = new Float64Array(nfft / 2 + 1);
  for (let k = 0; k <= nfft / 2; k++) p[k] = re[k] * re[k] + im[k] * im[k];
  return p;
}

const SR = 16000;
const N_SPK = 8; // 화자 8명
const N_UTT = 12; // 화자마다 문장 12개
const N_ENROLL = 3; // 등록에 3개
const BANDS = 24; // 장난감 임베딩의 길이 (진짜 ECAPA는 192, WavLM-SV는 512)
const EDGES = Array.from({ length: BANDS + 1 }, (_, i) => 150 * (7000 / 150) ** (i / BANDS)); // 150 Hz ~ 7 kHz를 로그 간격 24칸으로

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function rngOf(seed: number): { uniform: (a: number, b: number) => number; normal: () => number } {
  const r = mulberry32(seed);
  return { uniform: (a, b) => a + (b - a) * r(), normal: () => Math.sqrt(-2 * Math.log(Math.max(r(), 1e-12))) * Math.cos(2 * Math.PI * r()) };
}

type Spk = [number, number, number, number, number]; // f0 · F1 · F2 · F3 · tilt

function makeSpeakers(n: number = N_SPK, seed: number = 0): Spk[] {
  // 가상의 화자: 목소리 높이(f0) · 입 모양이 만드는 공명(F1 F2 F3) · 고음이 줄어드는 정도(tilt). (대체 경로: Zeroth Korean 대신)
  const r = rngOf(seed);
  return Array.from({ length: n }, () => [r.uniform(95, 260), r.uniform(300, 850), r.uniform(1000, 2300), r.uniform(2500, 3300), r.uniform(0.8, 1.4)] as Spk);
}

function voice(spk: Spk, seed: number, human: boolean = true, sec: number = 1.0): Float32Array {
  // 화자 spk가 문장 seed를 말한 1초 소리(합성). human=false면 TTS 같은 소리: 음높이 · 세기 · 입 모양이 늘 일정하고 잡음도 일정
  const r = rngOf(seed);
  const [f0, f1, f2, f3, tilt] = spk;
  const n = Math.floor(sec * SR);
  const forms = [f1, f2, f3].map((f) => f * (human ? r.uniform(0.95, 1.05) : 1)); // 말할 때마다 입 모양이 조금씩 다름
  const walk = new Float64Array(n + 1); // 걷는 값의 누적합 → 천천히 흔들리는 억양
  for (let i = 0; i < n; i++) walk[i + 1] = walk[i] + r.normal();
  const drift = Float64Array.from({ length: n }, (_, i) => (walk[Math.min(n, i + 1600)] - walk[Math.max(0, i - 1600)]) / 3200);
  const peak = drift.reduce((m, v) => Math.max(m, Math.abs(v)), 0) + 1e-9;
  const phase = new Float64Array(n);
  let acc = 0;
  for (let i = 0; i < n; i++) {
    acc += (2 * Math.PI * f0 * (1 + (human ? 0.12 : 0.04) * (drift[i] / peak))) / SR; // 억양 (TTS는 덜 흔들림)
    phase[i] = acc;
  }
  const y = new Float64Array(n);
  for (let k = 1; k <= Math.floor(7000 / f0); k++) {
    let amp = 0.01 * k ** -tilt;
    [90, 110, 150].forEach((bw, i) => (amp += k ** -tilt * Math.exp(-0.5 * ((k * f0 - forms[i]) / bw) ** 2)));
    for (let i = 0; i < n; i++) y[i] += amp * Math.sin(k * phase[i]);
  }
  if (human) {
    const rate = r.uniform(2, 4);
    const ph = r.uniform(0, 6.28);
    for (let i = 0; i < n; i++) y[i] *= 1 + 0.5 * Math.sin((2 * Math.PI * rate * i) / SR + ph); // 문장마다 다른 음절 세기
  }
  const top = y.reduce((m, v) => Math.max(m, Math.abs(v)), 0);
  const noise = human ? r.uniform(0.01, 0.03) : 0.02; // 숨소리 · 마이크 잡음 (TTS는 늘 같은 크기)
  return Float32Array.from(y, (v) => (0.5 * v) / top + noise * r.normal());
}

function embed(y: Float32Array): Float64Array {
  // 장난감 화자 임베딩: 소리의 평균 스펙트럼을 24칸으로 모아 로그를 취하고 전체 크기(평균)를 뺀다 → 크기와 상관없이 '목소리 모양'만 남음
  const p = new Float64Array(257);
  let frames = 0;
  for (let s = 0; s + 512 <= y.length; s += 256, frames++) {
    const re = new Float64Array(512);
    const im = new Float64Array(512);
    for (let i = 0; i < 512; i++) re[i] = y[s + i] * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / 511)); // 한(Hann) 창
    fft(re, im);
    for (let k = 0; k <= 256; k++) p[k] += re[k] * re[k] + im[k] * im[k];
  }
  const e = new Float64Array(BANDS);
  for (let b = 0; b < BANDS; b++) {
    let sum = 0;
    for (let k = 0; k <= 256; k++) {
      const f = (k * SR) / 512;
      if (f >= EDGES[b] && f < EDGES[b + 1]) sum += p[k] / frames;
    }
    e[b] = Math.log10(sum + 1e-10);
  }
  const mean = e.reduce((a, v) => a + v, 0) / BANDS;
  return e.map((v) => v - mean);
}

const dot = (a: ArrayLike<number>, b: ArrayLike<number>): number => {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * b[i];
  return s;
};
const norm = (a: ArrayLike<number>): number => Math.sqrt(dot(a, a));
const l2n = (e: ArrayLike<number>): Float64Array => Float64Array.from(e as ArrayLike<number>, (v) => v / norm(e)); // 길이(L2 노름)를 1로 → 내적 = 코사인 유사도
const meanVec = (vs: ArrayLike<number>[]): Float64Array => Float64Array.from({ length: vs[0].length }, (_, i) => vs.reduce((a, v) => a + v[i], 0) / vs.length);

function buildData(): [Spk[], Float64Array[][]] {
  // 화자 · 문장마다 소리를 만들고 임베딩 (E[화자][문장] = 길이 1짜리 24개 숫자)
  const spks = makeSpeakers();
  const E = spks.map((s, i) => Array.from({ length: N_UTT }, (_, u) => l2n(embed(voice(s, 1000 * i + u)))));
  return [spks, E];
}

function makeTrials(E: Float64Array[][], nEnroll: number = N_ENROLL): [number[], number[]] {
  // 본인 · 타인 시도 점수: 등록 템플릿 = 등록 문장 임베딩의 평균, 시험 = 나머지 문장
  const T = E.map((rows) => l2n(meanVec(rows.slice(0, nEnroll))));
  const tgt: number[] = [];
  const non: number[] = [];
  E.forEach((rows, s) => {
    for (let u = nEnroll; u < rows.length; u++) T.forEach((t, c) => (c === s ? tgt : non).push(dot(rows[u], t)));
  });
  return [tgt, non];
}

const mean = (a: number[]): number => a.reduce((x, y) => x + y, 0) / a.length;

function farFrr(tgt: number[], non: number[], th: number): [number, number] {
  const far = mean(non.map((v) => (v >= th ? 1 : 0))); // 남을 본인으로 받아들인 비율 → '타인 점수'에서 셈
  const frr = mean(tgt.map((v) => (v < th ? 1 : 0))); // 본인을 거절한 비율
  return [far, frr];
}

function eer(tgt: number[], non: number[]): [number, number] {
  // FAR과 FRR이 같아지는 지점의 오류율(EER)과 그때의 문턱
  const ths = [...tgt, ...non].sort((a, b) => a - b);
  let best = 0;
  let bestGap = Infinity;
  let val = 0;
  for (const t of ths) {
    const [far, frr] = farFrr(tgt, non, t);
    if (Math.abs(far - frr) < bestGap) {
      bestGap = Math.abs(far - frr);
      best = t;
      val = (far + frr) / 2;
    }
  }
  return [val, best];
}

function quantile(a: number[], q: number): number {
  // numpy의 기본(선형 보간) 분위수
  const s = [...a].sort((x, y) => x - y);
  const pos = (s.length - 1) * q;
  const lo = Math.floor(pos);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (pos - lo);
}

const thAtFar = (non: number[], targetFar: number): number => quantile(non, 1 - targetFar); // 타인 점수의 (1 − 목표 FAR) 분위수
const thAtFrr = (tgt: number[], targetFrr: number): number => quantile(tgt, targetFrr); // 본인 점수의 (목표 FRR) 분위수
const pFalseAccept = (far: number, n: number): number => 1 - (1 - far) ** n; // n명과 차례로 비교해 '한 번이라도' 문턱을 넘을 확률 (독립 가정)

class VoiceID {
  embedFn: (y: Float32Array) => Float64Array;
  th: number;
  db: Map<string, Float64Array> = new Map(); // 이름 → 등록 템플릿 (길이 1)
  constructor(embedFn: (y: Float32Array) => Float64Array, threshold: number) {
    this.embedFn = embedFn;
    this.th = threshold;
  }
  enroll(name: string, clips: Float32Array[]): void {
    // 등록: 몇 문장의 임베딩 평균
    this.db.set(name, l2n(meanVec(clips.map((c) => l2n(this.embedFn(c))))));
  }
  verify(name: string, clip: Float32Array): [boolean, number] {
    // 1:1 본인 확인
    const t = this.db.get(name);
    if (!t) throw new Error(`등록되지 않은 사람: ${name}`);
    const s = dot(l2n(this.embedFn(clip)), t);
    return [s >= this.th, s];
  }
  identify(clip: Float32Array): [string, Record<string, number>] {
    // 1:N 누구인가 (+ 모르는 사람 거절)
    const e = l2n(this.embedFn(clip));
    const scores: Record<string, number> = {};
    for (const [n, t] of this.db) scores[n] = dot(e, t);
    const best = Object.keys(scores).reduce((a, b) => (scores[b] > scores[a] ? b : a)); // 점수(값)가 가장 큰 '이름(키)'
    return [scores[best] >= this.th ? best : "모르는 사람", scores];
  }
}

const [, E] = buildData();
const [tgt, non] = makeTrials(E);
const [, thEer] = eer(tgt, non);
const pct = (v: number): string => `${(v * 100).toFixed(2)}%`;

// 1) 목표 FAR에서 문턱 거꾸로: 타인 점수의 (1 − 목표 FAR) 분위수
const rows: [string, number, number, number][] = [];
for (const [name, goal] of [["편의 우선 (FAR 5%)", 0.05], ["EER 지점", null], ["보안 (FAR 1%)", 0.01], ["은행급 (FAR 0.1%)", 0.001]] as [string, number | null][]) {
  const th = goal === null ? thEer : thAtFar(non, goal);
  const [far, frr] = farFrr(tgt, non, th);
  rows.push([name, th, far, frr]);
  console.log(`${name.padEnd(20)} 문턱 ${th.toFixed(3)} · FAR ${pct(far).padStart(6)} · FRR ${pct(frr).padStart(6)} · 받아들인 타인 시도 ${non.filter((v) => v >= th).length}번`);
}
const ths = [rows[0][1], rows[2][1], rows[3][1]]; // FAR 목표로 정한 세 문턱 (EER 지점은 분포가 안 겹치면 다른 자리에 잡힐 수 있어 뺌)
check(ths.every((t, i) => i === 0 || t >= ths[i - 1]) && Math.abs(rows[0][2] - 0.05) < 0.01 && Math.abs(rows[2][2] - 0.01) < 0.01, "보안을 높일수록 문턱이 올라가고 실제 FAR이 목표 근처예요.");
check(rows[3][3] >= rows[2][3] && rows[2][3] >= rows[1][3], "문턱을 올릴수록 본인 거절(FRR)이 늘어요: 보안과 편의는 맞바꿈이에요.");
console.log(`타인 시도는 ${non.length}번뿐 → FAR 0.1%는 약 ${(non.length * 0.001).toFixed(1)}번의 실수로 정한 문턱 (믿기 어려움)`);
check(non.length * 0.001 < 1, "시도가 적으면 0.1% 같은 작은 확률은 측정할 수 없어요.");

// 2) 거꾸로: 본인 거절(FRR)을 먼저 정하기 — 편의가 중요한 서비스
for (const g of [0.05, 0.01]) {
  const th = thAtFrr(tgt, g);
  const [far, frr] = farFrr(tgt, non, th);
  console.log(`FRR 목표 ${g * 100}% → 문턱 ${th.toFixed(3)} · 실제 FRR ${pct(frr)} · 그때 FAR ${pct(far)}`);
}
check([0.05, 0.01].every((g) => Math.abs(farFrr(tgt, non, thAtFrr(tgt, g))[1] - g) < 0.03), "본인 점수의 분위수로 문턱을 정하면 FRR이 목표 근처예요.");

// 3) 등록 인원이 n명이면 '모르는 사람'이 누군가로 받아들여질 확률: 1 − (1 − FAR)^n
const vals = [pFalseAccept(0.01, 1), pFalseAccept(0.01, 100), pFalseAccept(0.001, 1000)];
console.log("1:1 FAR 1% → n=1:", vals[0].toFixed(4), "· n=100:", vals[1].toFixed(4), "· FAR 0.1% n=1000:", vals[2].toFixed(4));
check([0.01, 0.634, 0.6323].every((w, i) => Math.abs(vals[i] - w) < 1e-3), "FAR이 작아도 등록 인원이 많으면 누군가와는 닮아 버려요.");
for (const n of [1, 5, 100, 10000]) console.log(`  1:1 FAR 1% · 등록 ${n.toLocaleString().padStart(6)}명 → ${(pFalseAccept(0.01, n) * 100).toFixed(1)}%`);
check(pFalseAccept(0.01, 10000) > 0.999, "수천 명이 등록되면 1:1 문턱만으로는 모르는 사람을 막을 수 없어요.");

enroll.typescript:
// D35 · Part 3 · 등록과 암호화 보관 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d35_enroll.ts   (합성 목소리 · 장난감 임베딩으로 모델 다운로드 · 인터넷 없이 실행)
//   화자 등록 · 검증과 민감정보 보관: 동의 → 템플릿(임베딩 평균) 만들기 → AES-GCM으로 암호화해 저장 → 꺼내 쓰기 → 철회하면 모두 삭제
import { createCipheriv, createDecipheriv, createHash, randomBytes } from "node:crypto";
function fft(re: Float64Array, im: Float64Array, inverse: boolean = false): void {
  // 제자리 FFT (길이는 2의 거듭제곱). inverse = true 이면 역변환(1/N 포함)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = ((inverse ? 2 : -2) * Math.PI) / len;
    const wr = Math.cos(ang);
    const wi = Math.sin(ang);
    for (let i = 0; i < n; i += len) {
      let cr = 1;
      let ci = 0;
      for (let k = 0; k < len / 2; k++) {
        const a = i + k;
        const b = a + len / 2;
        const tr = re[b] * cr - im[b] * ci;
        const ti = re[b] * ci + im[b] * cr;
        re[b] = re[a] - tr;
        im[b] = im[a] - ti;
        re[a] += tr;
        im[a] += ti;
        const nr = cr * wr - ci * wi;
        ci = cr * wi + ci * wr;
        cr = nr;
      }
    }
  }
  if (inverse)
    for (let i = 0; i < n; i++) {
      re[i] /= n;
      im[i] /= n;
    }
}

function powerSpectrum(x: ArrayLike<number>, nfft: number): Float64Array {
  // 실수 신호의 파워 스펙트럼(0 ~ 나이퀴스트, nfft/2 + 1칸). 모자라면 0으로 채움
  const re = new Float64Array(nfft);
  const im = new Float64Array(nfft);
  for (let i = 0; i < Math.min(nfft, x.length); i++) re[i] = x[i];
  fft(re, im);
  const p = new Float64Array(nfft / 2 + 1);
  for (let k = 0; k <= nfft / 2; k++) p[k] = re[k] * re[k] + im[k] * im[k];
  return p;
}

const SR = 16000;
const N_SPK = 8; // 화자 8명
const N_UTT = 12; // 화자마다 문장 12개
const N_ENROLL = 3; // 등록에 3개
const BANDS = 24; // 장난감 임베딩의 길이 (진짜 ECAPA는 192, WavLM-SV는 512)
const EDGES = Array.from({ length: BANDS + 1 }, (_, i) => 150 * (7000 / 150) ** (i / BANDS)); // 150 Hz ~ 7 kHz를 로그 간격 24칸으로

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function rngOf(seed: number): { uniform: (a: number, b: number) => number; normal: () => number } {
  const r = mulberry32(seed);
  return { uniform: (a, b) => a + (b - a) * r(), normal: () => Math.sqrt(-2 * Math.log(Math.max(r(), 1e-12))) * Math.cos(2 * Math.PI * r()) };
}

type Spk = [number, number, number, number, number]; // f0 · F1 · F2 · F3 · tilt

function makeSpeakers(n: number = N_SPK, seed: number = 0): Spk[] {
  // 가상의 화자: 목소리 높이(f0) · 입 모양이 만드는 공명(F1 F2 F3) · 고음이 줄어드는 정도(tilt). (대체 경로: Zeroth Korean 대신)
  const r = rngOf(seed);
  return Array.from({ length: n }, () => [r.uniform(95, 260), r.uniform(300, 850), r.uniform(1000, 2300), r.uniform(2500, 3300), r.uniform(0.8, 1.4)] as Spk);
}

function voice(spk: Spk, seed: number, human: boolean = true, sec: number = 1.0): Float32Array {
  // 화자 spk가 문장 seed를 말한 1초 소리(합성). human=false면 TTS 같은 소리: 음높이 · 세기 · 입 모양이 늘 일정하고 잡음도 일정
  const r = rngOf(seed);
  const [f0, f1, f2, f3, tilt] = spk;
  const n = Math.floor(sec * SR);
  const forms = [f1, f2, f3].map((f) => f * (human ? r.uniform(0.95, 1.05) : 1)); // 말할 때마다 입 모양이 조금씩 다름
  const walk = new Float64Array(n + 1); // 걷는 값의 누적합 → 천천히 흔들리는 억양
  for (let i = 0; i < n; i++) walk[i + 1] = walk[i] + r.normal();
  const drift = Float64Array.from({ length: n }, (_, i) => (walk[Math.min(n, i + 1600)] - walk[Math.max(0, i - 1600)]) / 3200);
  const peak = drift.reduce((m, v) => Math.max(m, Math.abs(v)), 0) + 1e-9;
  const phase = new Float64Array(n);
  let acc = 0;
  for (let i = 0; i < n; i++) {
    acc += (2 * Math.PI * f0 * (1 + (human ? 0.12 : 0.04) * (drift[i] / peak))) / SR; // 억양 (TTS는 덜 흔들림)
    phase[i] = acc;
  }
  const y = new Float64Array(n);
  for (let k = 1; k <= Math.floor(7000 / f0); k++) {
    let amp = 0.01 * k ** -tilt;
    [90, 110, 150].forEach((bw, i) => (amp += k ** -tilt * Math.exp(-0.5 * ((k * f0 - forms[i]) / bw) ** 2)));
    for (let i = 0; i < n; i++) y[i] += amp * Math.sin(k * phase[i]);
  }
  if (human) {
    const rate = r.uniform(2, 4);
    const ph = r.uniform(0, 6.28);
    for (let i = 0; i < n; i++) y[i] *= 1 + 0.5 * Math.sin((2 * Math.PI * rate * i) / SR + ph); // 문장마다 다른 음절 세기
  }
  const top = y.reduce((m, v) => Math.max(m, Math.abs(v)), 0);
  const noise = human ? r.uniform(0.01, 0.03) : 0.02; // 숨소리 · 마이크 잡음 (TTS는 늘 같은 크기)
  return Float32Array.from(y, (v) => (0.5 * v) / top + noise * r.normal());
}

function embed(y: Float32Array): Float64Array {
  // 장난감 화자 임베딩: 소리의 평균 스펙트럼을 24칸으로 모아 로그를 취하고 전체 크기(평균)를 뺀다 → 크기와 상관없이 '목소리 모양'만 남음
  const p = new Float64Array(257);
  let frames = 0;
  for (let s = 0; s + 512 <= y.length; s += 256, frames++) {
    const re = new Float64Array(512);
    const im = new Float64Array(512);
    for (let i = 0; i < 512; i++) re[i] = y[s + i] * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / 511)); // 한(Hann) 창
    fft(re, im);
    for (let k = 0; k <= 256; k++) p[k] += re[k] * re[k] + im[k] * im[k];
  }
  const e = new Float64Array(BANDS);
  for (let b = 0; b < BANDS; b++) {
    let sum = 0;
    for (let k = 0; k <= 256; k++) {
      const f = (k * SR) / 512;
      if (f >= EDGES[b] && f < EDGES[b + 1]) sum += p[k] / frames;
    }
    e[b] = Math.log10(sum + 1e-10);
  }
  const mean = e.reduce((a, v) => a + v, 0) / BANDS;
  return e.map((v) => v - mean);
}

const dot = (a: ArrayLike<number>, b: ArrayLike<number>): number => {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * b[i];
  return s;
};
const norm = (a: ArrayLike<number>): number => Math.sqrt(dot(a, a));
const l2n = (e: ArrayLike<number>): Float64Array => Float64Array.from(e as ArrayLike<number>, (v) => v / norm(e)); // 길이(L2 노름)를 1로 → 내적 = 코사인 유사도
const meanVec = (vs: ArrayLike<number>[]): Float64Array => Float64Array.from({ length: vs[0].length }, (_, i) => vs.reduce((a, v) => a + v[i], 0) / vs.length);

function buildData(): [Spk[], Float64Array[][]] {
  // 화자 · 문장마다 소리를 만들고 임베딩 (E[화자][문장] = 길이 1짜리 24개 숫자)
  const spks = makeSpeakers();
  const E = spks.map((s, i) => Array.from({ length: N_UTT }, (_, u) => l2n(embed(voice(s, 1000 * i + u)))));
  return [spks, E];
}

function makeTrials(E: Float64Array[][], nEnroll: number = N_ENROLL): [number[], number[]] {
  // 본인 · 타인 시도 점수: 등록 템플릿 = 등록 문장 임베딩의 평균, 시험 = 나머지 문장
  const T = E.map((rows) => l2n(meanVec(rows.slice(0, nEnroll))));
  const tgt: number[] = [];
  const non: number[] = [];
  E.forEach((rows, s) => {
    for (let u = nEnroll; u < rows.length; u++) T.forEach((t, c) => (c === s ? tgt : non).push(dot(rows[u], t)));
  });
  return [tgt, non];
}

const mean = (a: number[]): number => a.reduce((x, y) => x + y, 0) / a.length;

function farFrr(tgt: number[], non: number[], th: number): [number, number] {
  const far = mean(non.map((v) => (v >= th ? 1 : 0))); // 남을 본인으로 받아들인 비율 → '타인 점수'에서 셈
  const frr = mean(tgt.map((v) => (v < th ? 1 : 0))); // 본인을 거절한 비율
  return [far, frr];
}

function eer(tgt: number[], non: number[]): [number, number] {
  // FAR과 FRR이 같아지는 지점의 오류율(EER)과 그때의 문턱
  const ths = [...tgt, ...non].sort((a, b) => a - b);
  let best = 0;
  let bestGap = Infinity;
  let val = 0;
  for (const t of ths) {
    const [far, frr] = farFrr(tgt, non, t);
    if (Math.abs(far - frr) < bestGap) {
      bestGap = Math.abs(far - frr);
      best = t;
      val = (far + frr) / 2;
    }
  }
  return [val, best];
}

function quantile(a: number[], q: number): number {
  // numpy의 기본(선형 보간) 분위수
  const s = [...a].sort((x, y) => x - y);
  const pos = (s.length - 1) * q;
  const lo = Math.floor(pos);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (pos - lo);
}

const thAtFar = (non: number[], targetFar: number): number => quantile(non, 1 - targetFar); // 타인 점수의 (1 − 목표 FAR) 분위수
const thAtFrr = (tgt: number[], targetFrr: number): number => quantile(tgt, targetFrr); // 본인 점수의 (목표 FRR) 분위수
const pFalseAccept = (far: number, n: number): number => 1 - (1 - far) ** n; // n명과 차례로 비교해 '한 번이라도' 문턱을 넘을 확률 (독립 가정)

class VoiceID {
  embedFn: (y: Float32Array) => Float64Array;
  th: number;
  db: Map<string, Float64Array> = new Map(); // 이름 → 등록 템플릿 (길이 1)
  constructor(embedFn: (y: Float32Array) => Float64Array, threshold: number) {
    this.embedFn = embedFn;
    this.th = threshold;
  }
  enroll(name: string, clips: Float32Array[]): void {
    // 등록: 몇 문장의 임베딩 평균
    this.db.set(name, l2n(meanVec(clips.map((c) => l2n(this.embedFn(c))))));
  }
  verify(name: string, clip: Float32Array): [boolean, number] {
    // 1:1 본인 확인
    const t = this.db.get(name);
    if (!t) throw new Error(`등록되지 않은 사람: ${name}`);
    const s = dot(l2n(this.embedFn(clip)), t);
    return [s >= this.th, s];
  }
  identify(clip: Float32Array): [string, Record<string, number>] {
    // 1:N 누구인가 (+ 모르는 사람 거절)
    const e = l2n(this.embedFn(clip));
    const scores: Record<string, number> = {};
    for (const [n, t] of this.db) scores[n] = dot(e, t);
    const best = Object.keys(scores).reduce((a, b) => (scores[b] > scores[a] ? b : a)); // 점수(값)가 가장 큰 '이름(키)'
    return [scores[best] >= this.th ? best : "모르는 사람", scores];
  }
}

const [spks, E] = buildData();
const [tgt, non] = makeTrials(E);
const TH_SEC = thAtFar(non, 0.01); // '보안' 문턱 (FAR 1%)
const NAMES = ["김하늘", "김바다", "이소라"];
const VID = new VoiceID(embed, TH_SEC);
NAMES.forEach((name, i) => VID.enroll(name, Array.from({ length: N_ENROLL }, (_, u) => voice(spks[i], 1000 * i + u)))); // 등록: 3문장
console.log("등록:", [...VID.db.keys()], "· 템플릿 길이", VID.db.get("김하늘")?.length, "· 문턱", TH_SEC.toFixed(3));

const [okMe, sMe] = VID.verify("김하늘", voice(spks[0], 8)); // 본인이 건 전화
const [okOther, sOther] = VID.verify("김하늘", voice(spks[5], 1000 * 5 + 8)); // 남이 김하늘이라고 하며 건 전화
console.log(`본인 → 유사도 ${sMe.toFixed(3)} ${okMe ? "통과" : "다른 방법으로 확인"} · 타인 → 유사도 ${sOther.toFixed(3)} ${okOther ? "통과" : "다른 방법으로 확인"}`);
check(okMe && !okOther, "본인은 통과, 다른 사람이 사칭하면 거절돼야 해요.");

// 목소리 특징은 '민감정보': 동의 · 암호화 · 삭제
const CONSENT = { "동의 항목": "목소리 특징정보(임베딩) 수집 · 이용", 목적: "전화 예약 변경 시 본인 확인", "보관 기간": "동의일로부터 1년 또는 철회 시까지", "원본 녹음": "템플릿 생성 직후 삭제", "대체 수단": "생년월일 + 문자 인증 (동의 안 해도 서비스 이용 가능)", "별도 동의": "다른 개인정보 동의와 분리" };
const KEY = randomBytes(32); // 실서비스: KMS · 비밀 저장소에 보관. 화면 · 로그에 출력하지 않음

const userKey = (name: string): string => createHash("sha256").update(`hanbit-salt:${name}`).digest("hex").slice(0, 16); // 이름 대신 쓰는 번호 (실서비스: 비밀 소금으로 HMAC)

type Rec = { user: string; consent_id: string; model: string; created: string; expires: string; template: Buffer };

function seal(name: string, emb: Float64Array, consentId: string): Rec {
  const nonce = randomBytes(12);
  const c = createCipheriv("aes-256-gcm", KEY, nonce);
  c.setAAD(Buffer.from(userKey(name))); // 사용자 번호를 함께 묶어 다른 사람 자리로 옮기면 풀리지 않음
  const ct = Buffer.concat([c.update(Buffer.from(new Float32Array(emb).buffer)), c.final()]);
  return { user: userKey(name), consent_id: consentId, model: "toy-band24", created: "2026-11-12", expires: "2027-11-12", template: Buffer.concat([nonce, ct, c.getAuthTag()]) };
}

function unseal(rec: Rec): Float32Array {
  const b = rec.template;
  const d = createDecipheriv("aes-256-gcm", KEY, b.subarray(0, 12));
  d.setAAD(Buffer.from(rec.user));
  d.setAuthTag(b.subarray(b.length - 16));
  const raw = Buffer.concat([d.update(b.subarray(12, b.length - 16)), d.final()]); // 변조되었으면 여기서 오류
  return new Float32Array(raw.buffer.slice(raw.byteOffset, raw.byteOffset + raw.length));
}

const STORE = new Map<string, Rec>();
[...VID.db.entries()].forEach(([n, t], k) => STORE.set(userKey(n), seal(n, t, `C-2026-${String(k + 1).padStart(4, "0")}`)));
const rec = STORE.get(userKey("김하늘")) as Rec;
const raw = Buffer.from(new Float32Array(VID.db.get("김하늘") as Float64Array).buffer);
console.log("저장된 항목:", { ...rec, template: `${rec.template.subarray(0, 8).toString("hex")}… (${rec.template.length}바이트)` });
check(!rec.template.includes(raw) && !rec.template.subarray(12, 12 + raw.length).equals(raw), "저장소에는 암호문만 있어요(원래 숫자가 보이면 안 돼요).");
const back = unseal(rec);
check(back.length === BANDS && back.every((v, i) => Math.abs(v - (VID.db.get("김하늘") as Float64Array)[i]) < 1e-6), "열쇠로 풀면 같은 템플릿이 나와요.");

// 변조 · 바꿔치기는 풀리지 않는다
const flipped = Buffer.from(rec.template);
flipped[20] ^= 1;
const tampered: Rec = { ...rec, template: flipped };
const swapped: Rec = { ...(STORE.get(userKey("김바다")) as Rec), template: rec.template }; // 김하늘의 암호문을 김바다 자리에
let bad = 0;
for (const r of [tampered, swapped]) {
  try {
    unseal(r);
  } catch {
    bad++;
  }
}
console.log("변조 · 바꿔치기 시도 중 막힌 수:", bad, "/ 2");
check(bad === 2, "한 바이트만 바뀌어도, 다른 사람 자리로 옮겨도 복호화가 실패해야 해요.");

function forget(name: string): void {
  // 동의 철회: 저장소 · 메모리 모두에서 지운다
  STORE.delete(userKey(name));
  VID.db.delete(name);
}

forget("김하늘");
let gone = false;
try {
  VID.verify("김하늘", voice(spks[0], 8));
} catch {
  gone = true;
}
console.log("철회 뒤 남은 등록:", [...VID.db.keys()], "· 저장소", STORE.size, "건 · 필수 동의 항목", Object.keys(CONSENT).length, "개");
check(gone && !STORE.has(userKey("김하늘")) && STORE.size === 2, "철회하면 템플릿이 모두 사라져 더는 확인할 수 없어요.");

ident.typescript:
// D35 · Part 3 · 1:N 식별과 모르는 사람 거절 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d35_ident.ts   (합성 목소리 · 장난감 임베딩으로 모델 다운로드 · 인터넷 없이 실행)
//   1:N 식별: 등록한 가족 중 누구인지 고르고, 점수가 문턱 아래면 '모르는 사람'으로 거절. 등록 인원이 늘수록 잘못 받아들일 위험이 커진다
function fft(re: Float64Array, im: Float64Array, inverse: boolean = false): void {
  // 제자리 FFT (길이는 2의 거듭제곱). inverse = true 이면 역변환(1/N 포함)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = ((inverse ? 2 : -2) * Math.PI) / len;
    const wr = Math.cos(ang);
    const wi = Math.sin(ang);
    for (let i = 0; i < n; i += len) {
      let cr = 1;
      let ci = 0;
      for (let k = 0; k < len / 2; k++) {
        const a = i + k;
        const b = a + len / 2;
        const tr = re[b] * cr - im[b] * ci;
        const ti = re[b] * ci + im[b] * cr;
        re[b] = re[a] - tr;
        im[b] = im[a] - ti;
        re[a] += tr;
        im[a] += ti;
        const nr = cr * wr - ci * wi;
        ci = cr * wi + ci * wr;
        cr = nr;
      }
    }
  }
  if (inverse)
    for (let i = 0; i < n; i++) {
      re[i] /= n;
      im[i] /= n;
    }
}

function powerSpectrum(x: ArrayLike<number>, nfft: number): Float64Array {
  // 실수 신호의 파워 스펙트럼(0 ~ 나이퀴스트, nfft/2 + 1칸). 모자라면 0으로 채움
  const re = new Float64Array(nfft);
  const im = new Float64Array(nfft);
  for (let i = 0; i < Math.min(nfft, x.length); i++) re[i] = x[i];
  fft(re, im);
  const p = new Float64Array(nfft / 2 + 1);
  for (let k = 0; k <= nfft / 2; k++) p[k] = re[k] * re[k] + im[k] * im[k];
  return p;
}

const SR = 16000;
const N_SPK = 8; // 화자 8명
const N_UTT = 12; // 화자마다 문장 12개
const N_ENROLL = 3; // 등록에 3개
const BANDS = 24; // 장난감 임베딩의 길이 (진짜 ECAPA는 192, WavLM-SV는 512)
const EDGES = Array.from({ length: BANDS + 1 }, (_, i) => 150 * (7000 / 150) ** (i / BANDS)); // 150 Hz ~ 7 kHz를 로그 간격 24칸으로

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function rngOf(seed: number): { uniform: (a: number, b: number) => number; normal: () => number } {
  const r = mulberry32(seed);
  return { uniform: (a, b) => a + (b - a) * r(), normal: () => Math.sqrt(-2 * Math.log(Math.max(r(), 1e-12))) * Math.cos(2 * Math.PI * r()) };
}

type Spk = [number, number, number, number, number]; // f0 · F1 · F2 · F3 · tilt

function makeSpeakers(n: number = N_SPK, seed: number = 0): Spk[] {
  // 가상의 화자: 목소리 높이(f0) · 입 모양이 만드는 공명(F1 F2 F3) · 고음이 줄어드는 정도(tilt). (대체 경로: Zeroth Korean 대신)
  const r = rngOf(seed);
  return Array.from({ length: n }, () => [r.uniform(95, 260), r.uniform(300, 850), r.uniform(1000, 2300), r.uniform(2500, 3300), r.uniform(0.8, 1.4)] as Spk);
}

function voice(spk: Spk, seed: number, human: boolean = true, sec: number = 1.0): Float32Array {
  // 화자 spk가 문장 seed를 말한 1초 소리(합성). human=false면 TTS 같은 소리: 음높이 · 세기 · 입 모양이 늘 일정하고 잡음도 일정
  const r = rngOf(seed);
  const [f0, f1, f2, f3, tilt] = spk;
  const n = Math.floor(sec * SR);
  const forms = [f1, f2, f3].map((f) => f * (human ? r.uniform(0.95, 1.05) : 1)); // 말할 때마다 입 모양이 조금씩 다름
  const walk = new Float64Array(n + 1); // 걷는 값의 누적합 → 천천히 흔들리는 억양
  for (let i = 0; i < n; i++) walk[i + 1] = walk[i] + r.normal();
  const drift = Float64Array.from({ length: n }, (_, i) => (walk[Math.min(n, i + 1600)] - walk[Math.max(0, i - 1600)]) / 3200);
  const peak = drift.reduce((m, v) => Math.max(m, Math.abs(v)), 0) + 1e-9;
  const phase = new Float64Array(n);
  let acc = 0;
  for (let i = 0; i < n; i++) {
    acc += (2 * Math.PI * f0 * (1 + (human ? 0.12 : 0.04) * (drift[i] / peak))) / SR; // 억양 (TTS는 덜 흔들림)
    phase[i] = acc;
  }
  const y = new Float64Array(n);
  for (let k = 1; k <= Math.floor(7000 / f0); k++) {
    let amp = 0.01 * k ** -tilt;
    [90, 110, 150].forEach((bw, i) => (amp += k ** -tilt * Math.exp(-0.5 * ((k * f0 - forms[i]) / bw) ** 2)));
    for (let i = 0; i < n; i++) y[i] += amp * Math.sin(k * phase[i]);
  }
  if (human) {
    const rate = r.uniform(2, 4);
    const ph = r.uniform(0, 6.28);
    for (let i = 0; i < n; i++) y[i] *= 1 + 0.5 * Math.sin((2 * Math.PI * rate * i) / SR + ph); // 문장마다 다른 음절 세기
  }
  const top = y.reduce((m, v) => Math.max(m, Math.abs(v)), 0);
  const noise = human ? r.uniform(0.01, 0.03) : 0.02; // 숨소리 · 마이크 잡음 (TTS는 늘 같은 크기)
  return Float32Array.from(y, (v) => (0.5 * v) / top + noise * r.normal());
}

function embed(y: Float32Array): Float64Array {
  // 장난감 화자 임베딩: 소리의 평균 스펙트럼을 24칸으로 모아 로그를 취하고 전체 크기(평균)를 뺀다 → 크기와 상관없이 '목소리 모양'만 남음
  const p = new Float64Array(257);
  let frames = 0;
  for (let s = 0; s + 512 <= y.length; s += 256, frames++) {
    const re = new Float64Array(512);
    const im = new Float64Array(512);
    for (let i = 0; i < 512; i++) re[i] = y[s + i] * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / 511)); // 한(Hann) 창
    fft(re, im);
    for (let k = 0; k <= 256; k++) p[k] += re[k] * re[k] + im[k] * im[k];
  }
  const e = new Float64Array(BANDS);
  for (let b = 0; b < BANDS; b++) {
    let sum = 0;
    for (let k = 0; k <= 256; k++) {
      const f = (k * SR) / 512;
      if (f >= EDGES[b] && f < EDGES[b + 1]) sum += p[k] / frames;
    }
    e[b] = Math.log10(sum + 1e-10);
  }
  const mean = e.reduce((a, v) => a + v, 0) / BANDS;
  return e.map((v) => v - mean);
}

const dot = (a: ArrayLike<number>, b: ArrayLike<number>): number => {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * b[i];
  return s;
};
const norm = (a: ArrayLike<number>): number => Math.sqrt(dot(a, a));
const l2n = (e: ArrayLike<number>): Float64Array => Float64Array.from(e as ArrayLike<number>, (v) => v / norm(e)); // 길이(L2 노름)를 1로 → 내적 = 코사인 유사도
const meanVec = (vs: ArrayLike<number>[]): Float64Array => Float64Array.from({ length: vs[0].length }, (_, i) => vs.reduce((a, v) => a + v[i], 0) / vs.length);

function buildData(): [Spk[], Float64Array[][]] {
  // 화자 · 문장마다 소리를 만들고 임베딩 (E[화자][문장] = 길이 1짜리 24개 숫자)
  const spks = makeSpeakers();
  const E = spks.map((s, i) => Array.from({ length: N_UTT }, (_, u) => l2n(embed(voice(s, 1000 * i + u)))));
  return [spks, E];
}

function makeTrials(E: Float64Array[][], nEnroll: number = N_ENROLL): [number[], number[]] {
  // 본인 · 타인 시도 점수: 등록 템플릿 = 등록 문장 임베딩의 평균, 시험 = 나머지 문장
  const T = E.map((rows) => l2n(meanVec(rows.slice(0, nEnroll))));
  const tgt: number[] = [];
  const non: number[] = [];
  E.forEach((rows, s) => {
    for (let u = nEnroll; u < rows.length; u++) T.forEach((t, c) => (c === s ? tgt : non).push(dot(rows[u], t)));
  });
  return [tgt, non];
}

const mean = (a: number[]): number => a.reduce((x, y) => x + y, 0) / a.length;

function farFrr(tgt: number[], non: number[], th: number): [number, number] {
  const far = mean(non.map((v) => (v >= th ? 1 : 0))); // 남을 본인으로 받아들인 비율 → '타인 점수'에서 셈
  const frr = mean(tgt.map((v) => (v < th ? 1 : 0))); // 본인을 거절한 비율
  return [far, frr];
}

function eer(tgt: number[], non: number[]): [number, number] {
  // FAR과 FRR이 같아지는 지점의 오류율(EER)과 그때의 문턱
  const ths = [...tgt, ...non].sort((a, b) => a - b);
  let best = 0;
  let bestGap = Infinity;
  let val = 0;
  for (const t of ths) {
    const [far, frr] = farFrr(tgt, non, t);
    if (Math.abs(far - frr) < bestGap) {
      bestGap = Math.abs(far - frr);
      best = t;
      val = (far + frr) / 2;
    }
  }
  return [val, best];
}

function quantile(a: number[], q: number): number {
  // numpy의 기본(선형 보간) 분위수
  const s = [...a].sort((x, y) => x - y);
  const pos = (s.length - 1) * q;
  const lo = Math.floor(pos);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (pos - lo);
}

const thAtFar = (non: number[], targetFar: number): number => quantile(non, 1 - targetFar); // 타인 점수의 (1 − 목표 FAR) 분위수
const thAtFrr = (tgt: number[], targetFrr: number): number => quantile(tgt, targetFrr); // 본인 점수의 (목표 FRR) 분위수
const pFalseAccept = (far: number, n: number): number => 1 - (1 - far) ** n; // n명과 차례로 비교해 '한 번이라도' 문턱을 넘을 확률 (독립 가정)

class VoiceID {
  embedFn: (y: Float32Array) => Float64Array;
  th: number;
  db: Map<string, Float64Array> = new Map(); // 이름 → 등록 템플릿 (길이 1)
  constructor(embedFn: (y: Float32Array) => Float64Array, threshold: number) {
    this.embedFn = embedFn;
    this.th = threshold;
  }
  enroll(name: string, clips: Float32Array[]): void {
    // 등록: 몇 문장의 임베딩 평균
    this.db.set(name, l2n(meanVec(clips.map((c) => l2n(this.embedFn(c))))));
  }
  verify(name: string, clip: Float32Array): [boolean, number] {
    // 1:1 본인 확인
    const t = this.db.get(name);
    if (!t) throw new Error(`등록되지 않은 사람: ${name}`);
    const s = dot(l2n(this.embedFn(clip)), t);
    return [s >= this.th, s];
  }
  identify(clip: Float32Array): [string, Record<string, number>] {
    // 1:N 누구인가 (+ 모르는 사람 거절)
    const e = l2n(this.embedFn(clip));
    const scores: Record<string, number> = {};
    for (const [n, t] of this.db) scores[n] = dot(e, t);
    const best = Object.keys(scores).reduce((a, b) => (scores[b] > scores[a] ? b : a)); // 점수(값)가 가장 큰 '이름(키)'
    return [scores[best] >= this.th ? best : "모르는 사람", scores];
  }
}

const [spks, E] = buildData();
const [tgt, non] = makeTrials(E);
const TH_SEC = thAtFar(non, 0.01);
const FAMILY: Record<string, number> = { 김하늘: 0, 김바다: 1, 이소라: 2, 김구름: 3, 박노을: 4 }; // 가상의 이름 → 화자 번호
const STRANGERS = [5, 6, 7]; // 등록하지 않은 사람들

const VID = new VoiceID(embed, TH_SEC);
for (const [name, i] of Object.entries(FAMILY)) VID.enroll(name, Array.from({ length: N_ENROLL }, (_, u) => voice(spks[i], 1000 * i + u)));

let ok = 0;
let total = 0;
for (const [name, i] of Object.entries(FAMILY))
  for (let u = N_ENROLL; u < N_UTT; u++, total++) if (VID.identify(voice(spks[i], 1000 * i + u))[0] === name) ok++;
console.log(`가족 식별 정확도 ${ok}/${total} = ${((ok / total) * 100).toFixed(1)}%`);
check(ok / total > 0.7, "등록한 가족은 대부분 알아봐야 해요.");

let rej = 0;
let tot = 0;
for (const i of STRANGERS) for (let u = N_ENROLL; u < N_UTT; u++, tot++) if (VID.identify(voice(spks[i], 1000 * i + u))[0] === "모르는 사람") rej++;
console.log(`모르는 사람 거절 ${rej}/${tot} = ${((rej / tot) * 100).toFixed(1)}%`);
check(rej / tot > 0.85, "등록하지 않은 사람은 '모르는 사람'으로 거절해야 해요.");

const [who, scores] = VID.identify(voice(spks[2], 1000 * 2 + 5));
console.log("점수:", Object.fromEntries(Object.entries(scores).map(([n, s]) => [n, Math.round(s * 1000) / 1000])), "→", who);
check(who === "이소라" && Object.keys(scores).reduce((a, b) => (scores[b] > scores[a] ? b : a)) === "이소라", "가장 점수가 높은 이름이 답이에요(점수가 문턱을 넘을 때만).");

// 등록 인원 N이 늘면 '모르는 사람'이 누군가로 받아들여질 확률은? (임베딩 재사용)
const th = thAtFar(non, 0.05); // 효과가 눈에 보이게 문턱을 느슨하게(FAR 5%)
const far1 = farFrr(tgt, non, th)[0];
const r = rngOf(0);
const results: [number, number, number][] = [];
for (let N = 1; N < N_SPK; N++) {
  const fa: number[] = [];
  for (let rep = 0; rep < 60; rep++) {
    const ids = Array.from({ length: N_SPK }, (_, i) => i).sort(() => r.uniform(-1, 1)); // 무작위로 섞어 앞 N명을 등록자로
    const reg = ids.slice(0, N);
    const T = reg.map((s) => l2n(meanVec(E[s].slice(0, N_ENROLL))));
    const xs = ids.slice(N).flatMap((s) => E[s].slice(N_ENROLL));
    fa.push(mean(xs.map((x) => (Math.max(...T.map((t) => dot(x, t))) >= th ? 1 : 0))));
  }
  results.push([N, mean(fa), pFalseAccept(far1, N)]);
  console.log(`등록 ${N}명 → 모르는 사람 오수락 측정 ${(results[N - 1][1] * 100).toFixed(2).padStart(6)}% · 어림 1 − (1 − FAR)^N = ${(results[N - 1][2] * 100).toFixed(2).padStart(6)}%`);
}
check(results[results.length - 1][1] > results[0][1], "등록 인원이 늘수록 잘못 받아들이는 비율이 커져요.");
check(results.every(([, m, a]) => Math.abs(m - a) < 0.15), "측정값이 1 − (1 − FAR)^N 어림과 비슷해야 해요.");

spoof.typescript:
// D35 · Part 4 · 위조 음성 공격과 방어 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d35_spoof.ts   (합성 목소리 · 장난감 임베딩 · 합성 공격(복제 TTS · 재생)으로 모델 다운로드 · 인터넷 없이 실행)
//   위조 음성 공격과 방어: 화자 검증만으로는 복제 음성이 통과 → ② 무작위 문장(재생 차단) → ③ 위조 탐지(LFCC + 로지스틱 회귀, 복제 차단)로 겹겹이 막기
function fft(re: Float64Array, im: Float64Array, inverse: boolean = false): void {
  // 제자리 FFT (길이는 2의 거듭제곱). inverse = true 이면 역변환(1/N 포함)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = ((inverse ? 2 : -2) * Math.PI) / len;
    const wr = Math.cos(ang);
    const wi = Math.sin(ang);
    for (let i = 0; i < n; i += len) {
      let cr = 1;
      let ci = 0;
      for (let k = 0; k < len / 2; k++) {
        const a = i + k;
        const b = a + len / 2;
        const tr = re[b] * cr - im[b] * ci;
        const ti = re[b] * ci + im[b] * cr;
        re[b] = re[a] - tr;
        im[b] = im[a] - ti;
        re[a] += tr;
        im[a] += ti;
        const nr = cr * wr - ci * wi;
        ci = cr * wi + ci * wr;
        cr = nr;
      }
    }
  }
  if (inverse)
    for (let i = 0; i < n; i++) {
      re[i] /= n;
      im[i] /= n;
    }
}

function powerSpectrum(x: ArrayLike<number>, nfft: number): Float64Array {
  // 실수 신호의 파워 스펙트럼(0 ~ 나이퀴스트, nfft/2 + 1칸). 모자라면 0으로 채움
  const re = new Float64Array(nfft);
  const im = new Float64Array(nfft);
  for (let i = 0; i < Math.min(nfft, x.length); i++) re[i] = x[i];
  fft(re, im);
  const p = new Float64Array(nfft / 2 + 1);
  for (let k = 0; k <= nfft / 2; k++) p[k] = re[k] * re[k] + im[k] * im[k];
  return p;
}

const SR = 16000;
const N_SPK = 8; // 화자 8명
const N_UTT = 12; // 화자마다 문장 12개
const N_ENROLL = 3; // 등록에 3개
const BANDS = 24; // 장난감 임베딩의 길이 (진짜 ECAPA는 192, WavLM-SV는 512)
const EDGES = Array.from({ length: BANDS + 1 }, (_, i) => 150 * (7000 / 150) ** (i / BANDS)); // 150 Hz ~ 7 kHz를 로그 간격 24칸으로

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function rngOf(seed: number): { uniform: (a: number, b: number) => number; normal: () => number } {
  const r = mulberry32(seed);
  return { uniform: (a, b) => a + (b - a) * r(), normal: () => Math.sqrt(-2 * Math.log(Math.max(r(), 1e-12))) * Math.cos(2 * Math.PI * r()) };
}

type Spk = [number, number, number, number, number]; // f0 · F1 · F2 · F3 · tilt

function makeSpeakers(n: number = N_SPK, seed: number = 0): Spk[] {
  // 가상의 화자: 목소리 높이(f0) · 입 모양이 만드는 공명(F1 F2 F3) · 고음이 줄어드는 정도(tilt). (대체 경로: Zeroth Korean 대신)
  const r = rngOf(seed);
  return Array.from({ length: n }, () => [r.uniform(95, 260), r.uniform(300, 850), r.uniform(1000, 2300), r.uniform(2500, 3300), r.uniform(0.8, 1.4)] as Spk);
}

function voice(spk: Spk, seed: number, human: boolean = true, sec: number = 1.0): Float32Array {
  // 화자 spk가 문장 seed를 말한 1초 소리(합성). human=false면 TTS 같은 소리: 음높이 · 세기 · 입 모양이 늘 일정하고 잡음도 일정
  const r = rngOf(seed);
  const [f0, f1, f2, f3, tilt] = spk;
  const n = Math.floor(sec * SR);
  const forms = [f1, f2, f3].map((f) => f * (human ? r.uniform(0.95, 1.05) : 1)); // 말할 때마다 입 모양이 조금씩 다름
  const walk = new Float64Array(n + 1); // 걷는 값의 누적합 → 천천히 흔들리는 억양
  for (let i = 0; i < n; i++) walk[i + 1] = walk[i] + r.normal();
  const drift = Float64Array.from({ length: n }, (_, i) => (walk[Math.min(n, i + 1600)] - walk[Math.max(0, i - 1600)]) / 3200);
  const peak = drift.reduce((m, v) => Math.max(m, Math.abs(v)), 0) + 1e-9;
  const phase = new Float64Array(n);
  let acc = 0;
  for (let i = 0; i < n; i++) {
    acc += (2 * Math.PI * f0 * (1 + (human ? 0.12 : 0.04) * (drift[i] / peak))) / SR; // 억양 (TTS는 덜 흔들림)
    phase[i] = acc;
  }
  const y = new Float64Array(n);
  for (let k = 1; k <= Math.floor(7000 / f0); k++) {
    let amp = 0.01 * k ** -tilt;
    [90, 110, 150].forEach((bw, i) => (amp += k ** -tilt * Math.exp(-0.5 * ((k * f0 - forms[i]) / bw) ** 2)));
    for (let i = 0; i < n; i++) y[i] += amp * Math.sin(k * phase[i]);
  }
  if (human) {
    const rate = r.uniform(2, 4);
    const ph = r.uniform(0, 6.28);
    for (let i = 0; i < n; i++) y[i] *= 1 + 0.5 * Math.sin((2 * Math.PI * rate * i) / SR + ph); // 문장마다 다른 음절 세기
  }
  const top = y.reduce((m, v) => Math.max(m, Math.abs(v)), 0);
  const noise = human ? r.uniform(0.01, 0.03) : 0.02; // 숨소리 · 마이크 잡음 (TTS는 늘 같은 크기)
  return Float32Array.from(y, (v) => (0.5 * v) / top + noise * r.normal());
}

function embed(y: Float32Array): Float64Array {
  // 장난감 화자 임베딩: 소리의 평균 스펙트럼을 24칸으로 모아 로그를 취하고 전체 크기(평균)를 뺀다 → 크기와 상관없이 '목소리 모양'만 남음
  const p = new Float64Array(257);
  let frames = 0;
  for (let s = 0; s + 512 <= y.length; s += 256, frames++) {
    const re = new Float64Array(512);
    const im = new Float64Array(512);
    for (let i = 0; i < 512; i++) re[i] = y[s + i] * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / 511)); // 한(Hann) 창
    fft(re, im);
    for (let k = 0; k <= 256; k++) p[k] += re[k] * re[k] + im[k] * im[k];
  }
  const e = new Float64Array(BANDS);
  for (let b = 0; b < BANDS; b++) {
    let sum = 0;
    for (let k = 0; k <= 256; k++) {
      const f = (k * SR) / 512;
      if (f >= EDGES[b] && f < EDGES[b + 1]) sum += p[k] / frames;
    }
    e[b] = Math.log10(sum + 1e-10);
  }
  const mean = e.reduce((a, v) => a + v, 0) / BANDS;
  return e.map((v) => v - mean);
}

const dot = (a: ArrayLike<number>, b: ArrayLike<number>): number => {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * b[i];
  return s;
};
const norm = (a: ArrayLike<number>): number => Math.sqrt(dot(a, a));
const l2n = (e: ArrayLike<number>): Float64Array => Float64Array.from(e as ArrayLike<number>, (v) => v / norm(e)); // 길이(L2 노름)를 1로 → 내적 = 코사인 유사도
const meanVec = (vs: ArrayLike<number>[]): Float64Array => Float64Array.from({ length: vs[0].length }, (_, i) => vs.reduce((a, v) => a + v[i], 0) / vs.length);

function buildData(): [Spk[], Float64Array[][]] {
  // 화자 · 문장마다 소리를 만들고 임베딩 (E[화자][문장] = 길이 1짜리 24개 숫자)
  const spks = makeSpeakers();
  const E = spks.map((s, i) => Array.from({ length: N_UTT }, (_, u) => l2n(embed(voice(s, 1000 * i + u)))));
  return [spks, E];
}

function makeTrials(E: Float64Array[][], nEnroll: number = N_ENROLL): [number[], number[]] {
  // 본인 · 타인 시도 점수: 등록 템플릿 = 등록 문장 임베딩의 평균, 시험 = 나머지 문장
  const T = E.map((rows) => l2n(meanVec(rows.slice(0, nEnroll))));
  const tgt: number[] = [];
  const non: number[] = [];
  E.forEach((rows, s) => {
    for (let u = nEnroll; u < rows.length; u++) T.forEach((t, c) => (c === s ? tgt : non).push(dot(rows[u], t)));
  });
  return [tgt, non];
}

const mean = (a: number[]): number => a.reduce((x, y) => x + y, 0) / a.length;

function farFrr(tgt: number[], non: number[], th: number): [number, number] {
  const far = mean(non.map((v) => (v >= th ? 1 : 0))); // 남을 본인으로 받아들인 비율 → '타인 점수'에서 셈
  const frr = mean(tgt.map((v) => (v < th ? 1 : 0))); // 본인을 거절한 비율
  return [far, frr];
}

function eer(tgt: number[], non: number[]): [number, number] {
  // FAR과 FRR이 같아지는 지점의 오류율(EER)과 그때의 문턱
  const ths = [...tgt, ...non].sort((a, b) => a - b);
  let best = 0;
  let bestGap = Infinity;
  let val = 0;
  for (const t of ths) {
    const [far, frr] = farFrr(tgt, non, t);
    if (Math.abs(far - frr) < bestGap) {
      bestGap = Math.abs(far - frr);
      best = t;
      val = (far + frr) / 2;
    }
  }
  return [val, best];
}

function quantile(a: number[], q: number): number {
  // numpy의 기본(선형 보간) 분위수
  const s = [...a].sort((x, y) => x - y);
  const pos = (s.length - 1) * q;
  const lo = Math.floor(pos);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (pos - lo);
}

const thAtFar = (non: number[], targetFar: number): number => quantile(non, 1 - targetFar); // 타인 점수의 (1 − 목표 FAR) 분위수
const thAtFrr = (tgt: number[], targetFrr: number): number => quantile(tgt, targetFrr); // 본인 점수의 (목표 FRR) 분위수
const pFalseAccept = (far: number, n: number): number => 1 - (1 - far) ** n; // n명과 차례로 비교해 '한 번이라도' 문턱을 넘을 확률 (독립 가정)

class VoiceID {
  embedFn: (y: Float32Array) => Float64Array;
  th: number;
  db: Map<string, Float64Array> = new Map(); // 이름 → 등록 템플릿 (길이 1)
  constructor(embedFn: (y: Float32Array) => Float64Array, threshold: number) {
    this.embedFn = embedFn;
    this.th = threshold;
  }
  enroll(name: string, clips: Float32Array[]): void {
    // 등록: 몇 문장의 임베딩 평균
    this.db.set(name, l2n(meanVec(clips.map((c) => l2n(this.embedFn(c))))));
  }
  verify(name: string, clip: Float32Array): [boolean, number] {
    // 1:1 본인 확인
    const t = this.db.get(name);
    if (!t) throw new Error(`등록되지 않은 사람: ${name}`);
    const s = dot(l2n(this.embedFn(clip)), t);
    return [s >= this.th, s];
  }
  identify(clip: Float32Array): [string, Record<string, number>] {
    // 1:N 누구인가 (+ 모르는 사람 거절)
    const e = l2n(this.embedFn(clip));
    const scores: Record<string, number> = {};
    for (const [n, t] of this.db) scores[n] = dot(e, t);
    const best = Object.keys(scores).reduce((a, b) => (scores[b] > scores[a] ? b : a)); // 점수(값)가 가장 큰 '이름(키)'
    return [scores[best] >= this.th ? best : "모르는 사람", scores];
  }
}

const DCT_COS = Array.from({ length: 20 }, (_, q) => Float64Array.from({ length: 257 }, (_, k) => Math.cos((Math.PI * (2 * k + 1) * q) / 514))); // DCT-II 표 (미리 계산)

function lfcc(y: Float32Array, n: number = 20): Float64Array {
  // 위조 탐지에서 많이 쓰는 특징: 로그 스펙트럼 → 켑스트럼(DCT). 시간에 따른 평균 · 흔들림 · 변화 속도를 이어 60개 숫자로
  const C: Float64Array[] = [];
  for (let s = 0; s + 512 <= y.length; s += 160) {
    const re = new Float64Array(512);
    const im = new Float64Array(512);
    for (let i = 0; i < 512; i++) re[i] = y[s + i] * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / 511));
    fft(re, im);
    const logP = Float64Array.from({ length: 257 }, (_, k) => Math.log(re[k] * re[k] + im[k] * im[k] + 1e-10)); // 멜이 아니라 고르게 257개 주파수
    C.push(Float64Array.from({ length: n }, (_, q) => (q === 0 ? Math.sqrt(1 / 257) : Math.sqrt(2 / 257)) * logP.reduce((a, v, k) => a + v * DCT_COS[q][k], 0))); // 로그 스펙트럼 → 켑스트럼(DCT-II)
  }
  const col = (q: number): number[] => C.map((c) => c[q]);
  const std = (a: number[]): number => Math.sqrt(mean(a.map((v) => (v - mean(a)) ** 2)));
  const diff = (a: number[]): number[] => a.slice(1).map((v, i) => v - a[i]);
  const idx = Array.from({ length: n }, (_, q) => q);
  return Float64Array.from([...idx.map((q) => mean(col(q))), ...idx.map((q) => std(col(q))), ...idx.map((q) => std(diff(col(q))))]);
}

class Detector {
  // 표준화 + 로지스틱 회귀(경사 하강법). 0에 가까우면 진짜 사람, 1에 가까우면 위조
  mu: Float64Array = new Float64Array(0);
  sd: Float64Array = new Float64Array(0);
  w: Float64Array = new Float64Array(0);
  b: number = 0;
  fit(X: Float64Array[], y: number[], l2: number = 0.01, steps: number = 3000, lr: number = 0.3): Detector {
    const d = X[0].length;
    this.mu = Float64Array.from({ length: d }, (_, j) => mean(X.map((r) => r[j])));
    this.sd = Float64Array.from({ length: d }, (_, j) => Math.sqrt(mean(X.map((r) => (r[j] - this.mu[j]) ** 2))) + 1e-9);
    const Z = X.map((r) => r.map((v, j) => (v - this.mu[j]) / this.sd[j]));
    this.w = new Float64Array(d);
    this.b = 0;
    for (let it = 0; it < steps; it++) {
      const gw = new Float64Array(d);
      let gb = 0;
      Z.forEach((z, i) => {
        const err = 1 / (1 + Math.exp(-(dot(z, this.w) + this.b))) - y[i];
        for (let j = 0; j < d; j++) gw[j] += (err * z[j]) / Z.length;
        gb += err / Z.length;
      });
      for (let j = 0; j < d; j++) this.w[j] -= lr * (gw[j] + l2 * this.w[j]);
      this.b -= lr * gb;
    }
    return this;
  }
  score(clip: Float32Array): number {
    const f = lfcc(clip);
    const z = f.map((v, j) => (v - this.mu[j]) / this.sd[j]);
    return 1 / (1 + Math.exp(-(dot(z, this.w) + this.b))); // 위조일 확률
  }
}

const [spks, E] = buildData();
const [, non] = makeTrials(E);
const TH_SEC = thAtFar(non, 0.05); // 이 시험에서는 FAR 5% 문턱 (시도가 적어 1%는 본인도 많이 거절돼 비교가 어려움)
const FAMILY: [string, number][] = [["김하늘", 0], ["김바다", 1], ["이소라", 2], ["김구름", 3], ["박노을", 4]];
const STRANGERS = [5, 6, 7];
const VID = new VoiceID(embed, TH_SEC);
for (const [name, i] of FAMILY) VID.enroll(name, Array.from({ length: N_ENROLL }, (_, u) => voice(spks[i], 1000 * i + u)));

function replay(y: Float32Array, seed: number = 0): Float32Array {
  // 유출 녹음을 스마트폰 스피커로 틀어 전화기 마이크에 들려줌: 작은 스피커(저음 · 고음 손실) + 방 울림 + 찌그러짐 + 잡음 (대체 경로: 진짜 재생 녹음 대신)
  const r = rngOf(seed);
  const aHi = Math.exp((-2 * Math.PI * 250) / SR); // 250 Hz 아래를 깎는 1차 필터
  const aLo = 1 - Math.exp((-2 * Math.PI * 6000) / SR); // 6 kHz 위를 깎는 1차 필터
  let lp1 = 0;
  let lp2 = 0;
  let hpPrevX = 0;
  let hpPrevY = 0;
  const band = Float32Array.from(y, (v) => {
    const h = aHi * (hpPrevY + v - hpPrevX);
    hpPrevX = v;
    hpPrevY = h;
    lp1 += aLo * (h - lp1);
    lp2 += aLo * (lp1 - lp2);
    return lp2;
  });
  const rir = Float64Array.from({ length: 2000 }, (_, i) => r.normal() * Math.exp(-i / 600));
  rir[0] = 8.0;
  const sumAbs = rir.reduce((a, v) => a + Math.abs(v), 0);
  const out = new Float64Array(y.length);
  for (let i = 0; i < y.length; i++) for (let k = 0; k < rir.length && i + k < y.length; k++) out[i + k] += band[i] * rir[k];
  const top = out.reduce((m, v) => Math.max(m, Math.abs(v)), 0) + 1e-9;
  return Float32Array.from(out, (v) => (Math.tanh((2.0 * v) / top) / 2.0) * 0.7 + 0.003 * r.normal()); // 스피커의 찌그러짐 + 잡음
}

// 위조 탐지기 학습: 진짜 사람(등록 문장들) vs TTS 같은 소리(공격 대상이 아닌 다른 화자 16명)
const realTrain = spks.flatMap((s, i) => Array.from({ length: 6 }, (_, u) => voice(s, 1000 * i + u)));
const fakeTrain = makeSpeakers(16, 99).flatMap((s, k) => Array.from({ length: 6 }, (_, j) => voice(s, 500 + 6 * k + j, false)));
const X = [...realTrain, ...fakeTrain].map((y) => lfcc(y));
const DET = new Detector().fit(X, [...realTrain.map(() => 0), ...fakeTrain.map(() => 1)]);
console.log(`탐지기 학습: 진짜 ${realTrain.length}개 · 위조(TTS) ${fakeTrain.length}개 · 특징 ${X[0].length}개`);

// 공격 모음: 전화 한 통 = (종류, 하나가 읽어 달라고 한 문장, 실제로 읽은 문장, 소리)
type Attempt = { kind: string; speaker_ok: boolean; text_ok: boolean; live_ok: boolean };
const r = rngOf(1);
const digits = (): string => [0, 1, 2].map(() => Math.floor(r.uniform(0, 10))).join("-");
const ATTACKS: Attempt[] = [];
FAMILY.forEach(([name, i], k) => {
  for (let j = 0; j < 4; j++) {
    const challenge = digits(); // 무작위 숫자 문장 (예: 3-1-4)
    const leaked = digits(); // 예전에 유출된 녹음 속 문장 (우연히 같을 확률은 낮음)
    const o = STRANGERS[(k + j) % STRANGERS.length];
    const cand: [string, string, Float32Array][] = [
      ["본인", challenge, voice(spks[i], 7000 + 10 * k + j)],
      ["사칭 (다른 사람)", challenge, voice(spks[o], 7100 + 10 * k + j)],
      ["복제 (TTS)", challenge, voice(spks[i], 9000 + 10 * k + j, false)], // 목소리 모양은 따라 하지만 TTS 특유의 일정함이 남음
      ["재생 (유출 녹음)", leaked, replay(voice(spks[i], 8000 + 10 * k + j), j)],
    ];
    for (const [kind, spoken, clip] of cand) ATTACKS.push({ kind, speaker_ok: VID.verify(name, clip)[0], text_ok: spoken === challenge, live_ok: DET.score(clip) < 0.5 }); // 받아쓰기 흉내: 읽은 문장 = 요청 문장?
  }
});
const KINDS = [...new Set(ATTACKS.map((a) => a.kind))];

function gate(x: Omit<Attempt, "kind">): string {
  // 세 관문을 차례로: ① 목소리 → ② 문장 → ③ 위조. 처음 막힌 관문의 이름, 모두 통과하면 '통과'
  if (!x.speaker_ok) return "목소리";
  if (!x.text_ok) return "문장";
  if (!x.live_ok) return "위조";
  return "통과";
}

const cs = (s: boolean, t: boolean, l: boolean): Omit<Attempt, "kind"> => ({ speaker_ok: s, text_ok: t, live_ok: l });
check([cs(true, true, true), cs(false, true, true), cs(true, false, true), cs(true, true, false), cs(false, false, false), cs(true, false, false)].map(gate).join() === "통과,목소리,문장,위조,목소리,문장", "목소리 → 문장 → 위조 순서로 검사해 처음 막힌 관문을 돌려줘야 해요.");

const table: Record<string, number[]> = {};
for (const kind of KINDS) {
  const rows = ATTACKS.filter((a) => a.kind === kind);
  const rate = (f: (a: Attempt) => boolean): number => rows.filter(f).length / rows.length;
  table[kind] = [rate((a) => a.speaker_ok), rate((a) => a.speaker_ok && a.text_ok), rate((a) => gate(a) === "통과")];
  const p = (v: number): string => `${Math.round(v * 100)}%`.padStart(5);
  console.log(`${kind.padEnd(14)} ① 화자 검증만 ${p(table[kind][0])} · ② + 무작위 문장 ${p(table[kind][1])} · ③ + 위조 탐지(최종 통과) ${p(table[kind][2])}`);
}
console.log("'본인' 줄 = 본인이 통과한 비율(높을수록 좋음) · 나머지 줄 = 공격이 통과한 비율(낮을수록 좋음)");
check(table["본인"][2] >= 0.7, "본인은 세 관문을 대부분 통과해야 해요.");
check(table["사칭 (다른 사람)"][0] <= 0.15, "다른 사람의 사칭은 화자 검증만으로도 대부분 막혀요.");
check(table["복제 (TTS)"][0] >= 0.8 && table["복제 (TTS)"][1] >= 0.8 && table["복제 (TTS)"][2] <= 0.1, "복제 음성은 화자 검증 · 문장 확인을 통과하지만 위조 탐지가 막아요.");
check(table["재생 (유출 녹음)"][0] >= 0.5 && table["재생 (유출 녹음)"][1] <= 0.1, "유출 녹음을 틀면 목소리는 통과해도 무작위 문장에서 막혀요.");
check(KINDS.filter((k) => k !== "본인").every((k) => table[k][2] <= 0.15), "겹겹이 막으면 공격이 통과하는 비율이 15% 이하예요.");

console.log("관문마다 걸린 이유 (예시 3개):");
for (const kind of KINDS.slice(1)) console.log(`  ${kind.padEnd(14)} → ${gate(ATTACKS.find((a) => a.kind === kind) as Attempt)}`);
const counts: Record<string, number> = {};
for (const a of ATTACKS) counts[`${a.kind}/${gate(a)}`] = (counts[`${a.kind}/${gate(a)}`] ?? 0) + 1;
console.log("종류별 결과:", counts);

recap.typescript:
// D35 · Part 4 · 정리 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d35_recap.ts   (합성 목소리 · 핵심 공식을 한 번씩 확인)
//   화자 임베딩 · 검증 · 운영 문턱 · 보관 · 위조 방어의 핵심 공식을 정리표 순서대로 한 번씩 확인
import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";
function fft(re: Float64Array, im: Float64Array, inverse: boolean = false): void {
  // 제자리 FFT (길이는 2의 거듭제곱). inverse = true 이면 역변환(1/N 포함)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = ((inverse ? 2 : -2) * Math.PI) / len;
    const wr = Math.cos(ang);
    const wi = Math.sin(ang);
    for (let i = 0; i < n; i += len) {
      let cr = 1;
      let ci = 0;
      for (let k = 0; k < len / 2; k++) {
        const a = i + k;
        const b = a + len / 2;
        const tr = re[b] * cr - im[b] * ci;
        const ti = re[b] * ci + im[b] * cr;
        re[b] = re[a] - tr;
        im[b] = im[a] - ti;
        re[a] += tr;
        im[a] += ti;
        const nr = cr * wr - ci * wi;
        ci = cr * wi + ci * wr;
        cr = nr;
      }
    }
  }
  if (inverse)
    for (let i = 0; i < n; i++) {
      re[i] /= n;
      im[i] /= n;
    }
}

function powerSpectrum(x: ArrayLike<number>, nfft: number): Float64Array {
  // 실수 신호의 파워 스펙트럼(0 ~ 나이퀴스트, nfft/2 + 1칸). 모자라면 0으로 채움
  const re = new Float64Array(nfft);
  const im = new Float64Array(nfft);
  for (let i = 0; i < Math.min(nfft, x.length); i++) re[i] = x[i];
  fft(re, im);
  const p = new Float64Array(nfft / 2 + 1);
  for (let k = 0; k <= nfft / 2; k++) p[k] = re[k] * re[k] + im[k] * im[k];
  return p;
}

const SR = 16000;
const N_SPK = 8; // 화자 8명
const N_UTT = 12; // 화자마다 문장 12개
const N_ENROLL = 3; // 등록에 3개
const BANDS = 24; // 장난감 임베딩의 길이 (진짜 ECAPA는 192, WavLM-SV는 512)
const EDGES = Array.from({ length: BANDS + 1 }, (_, i) => 150 * (7000 / 150) ** (i / BANDS)); // 150 Hz ~ 7 kHz를 로그 간격 24칸으로

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function rngOf(seed: number): { uniform: (a: number, b: number) => number; normal: () => number } {
  const r = mulberry32(seed);
  return { uniform: (a, b) => a + (b - a) * r(), normal: () => Math.sqrt(-2 * Math.log(Math.max(r(), 1e-12))) * Math.cos(2 * Math.PI * r()) };
}

type Spk = [number, number, number, number, number]; // f0 · F1 · F2 · F3 · tilt

function makeSpeakers(n: number = N_SPK, seed: number = 0): Spk[] {
  // 가상의 화자: 목소리 높이(f0) · 입 모양이 만드는 공명(F1 F2 F3) · 고음이 줄어드는 정도(tilt). (대체 경로: Zeroth Korean 대신)
  const r = rngOf(seed);
  return Array.from({ length: n }, () => [r.uniform(95, 260), r.uniform(300, 850), r.uniform(1000, 2300), r.uniform(2500, 3300), r.uniform(0.8, 1.4)] as Spk);
}

function voice(spk: Spk, seed: number, human: boolean = true, sec: number = 1.0): Float32Array {
  // 화자 spk가 문장 seed를 말한 1초 소리(합성). human=false면 TTS 같은 소리: 음높이 · 세기 · 입 모양이 늘 일정하고 잡음도 일정
  const r = rngOf(seed);
  const [f0, f1, f2, f3, tilt] = spk;
  const n = Math.floor(sec * SR);
  const forms = [f1, f2, f3].map((f) => f * (human ? r.uniform(0.95, 1.05) : 1)); // 말할 때마다 입 모양이 조금씩 다름
  const walk = new Float64Array(n + 1); // 걷는 값의 누적합 → 천천히 흔들리는 억양
  for (let i = 0; i < n; i++) walk[i + 1] = walk[i] + r.normal();
  const drift = Float64Array.from({ length: n }, (_, i) => (walk[Math.min(n, i + 1600)] - walk[Math.max(0, i - 1600)]) / 3200);
  const peak = drift.reduce((m, v) => Math.max(m, Math.abs(v)), 0) + 1e-9;
  const phase = new Float64Array(n);
  let acc = 0;
  for (let i = 0; i < n; i++) {
    acc += (2 * Math.PI * f0 * (1 + (human ? 0.12 : 0.04) * (drift[i] / peak))) / SR; // 억양 (TTS는 덜 흔들림)
    phase[i] = acc;
  }
  const y = new Float64Array(n);
  for (let k = 1; k <= Math.floor(7000 / f0); k++) {
    let amp = 0.01 * k ** -tilt;
    [90, 110, 150].forEach((bw, i) => (amp += k ** -tilt * Math.exp(-0.5 * ((k * f0 - forms[i]) / bw) ** 2)));
    for (let i = 0; i < n; i++) y[i] += amp * Math.sin(k * phase[i]);
  }
  if (human) {
    const rate = r.uniform(2, 4);
    const ph = r.uniform(0, 6.28);
    for (let i = 0; i < n; i++) y[i] *= 1 + 0.5 * Math.sin((2 * Math.PI * rate * i) / SR + ph); // 문장마다 다른 음절 세기
  }
  const top = y.reduce((m, v) => Math.max(m, Math.abs(v)), 0);
  const noise = human ? r.uniform(0.01, 0.03) : 0.02; // 숨소리 · 마이크 잡음 (TTS는 늘 같은 크기)
  return Float32Array.from(y, (v) => (0.5 * v) / top + noise * r.normal());
}

function embed(y: Float32Array): Float64Array {
  // 장난감 화자 임베딩: 소리의 평균 스펙트럼을 24칸으로 모아 로그를 취하고 전체 크기(평균)를 뺀다 → 크기와 상관없이 '목소리 모양'만 남음
  const p = new Float64Array(257);
  let frames = 0;
  for (let s = 0; s + 512 <= y.length; s += 256, frames++) {
    const re = new Float64Array(512);
    const im = new Float64Array(512);
    for (let i = 0; i < 512; i++) re[i] = y[s + i] * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / 511)); // 한(Hann) 창
    fft(re, im);
    for (let k = 0; k <= 256; k++) p[k] += re[k] * re[k] + im[k] * im[k];
  }
  const e = new Float64Array(BANDS);
  for (let b = 0; b < BANDS; b++) {
    let sum = 0;
    for (let k = 0; k <= 256; k++) {
      const f = (k * SR) / 512;
      if (f >= EDGES[b] && f < EDGES[b + 1]) sum += p[k] / frames;
    }
    e[b] = Math.log10(sum + 1e-10);
  }
  const mean = e.reduce((a, v) => a + v, 0) / BANDS;
  return e.map((v) => v - mean);
}

const dot = (a: ArrayLike<number>, b: ArrayLike<number>): number => {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * b[i];
  return s;
};
const norm = (a: ArrayLike<number>): number => Math.sqrt(dot(a, a));
const l2n = (e: ArrayLike<number>): Float64Array => Float64Array.from(e as ArrayLike<number>, (v) => v / norm(e)); // 길이(L2 노름)를 1로 → 내적 = 코사인 유사도
const meanVec = (vs: ArrayLike<number>[]): Float64Array => Float64Array.from({ length: vs[0].length }, (_, i) => vs.reduce((a, v) => a + v[i], 0) / vs.length);

function buildData(): [Spk[], Float64Array[][]] {
  // 화자 · 문장마다 소리를 만들고 임베딩 (E[화자][문장] = 길이 1짜리 24개 숫자)
  const spks = makeSpeakers();
  const E = spks.map((s, i) => Array.from({ length: N_UTT }, (_, u) => l2n(embed(voice(s, 1000 * i + u)))));
  return [spks, E];
}

function makeTrials(E: Float64Array[][], nEnroll: number = N_ENROLL): [number[], number[]] {
  // 본인 · 타인 시도 점수: 등록 템플릿 = 등록 문장 임베딩의 평균, 시험 = 나머지 문장
  const T = E.map((rows) => l2n(meanVec(rows.slice(0, nEnroll))));
  const tgt: number[] = [];
  const non: number[] = [];
  E.forEach((rows, s) => {
    for (let u = nEnroll; u < rows.length; u++) T.forEach((t, c) => (c === s ? tgt : non).push(dot(rows[u], t)));
  });
  return [tgt, non];
}

const mean = (a: number[]): number => a.reduce((x, y) => x + y, 0) / a.length;

function farFrr(tgt: number[], non: number[], th: number): [number, number] {
  const far = mean(non.map((v) => (v >= th ? 1 : 0))); // 남을 본인으로 받아들인 비율 → '타인 점수'에서 셈
  const frr = mean(tgt.map((v) => (v < th ? 1 : 0))); // 본인을 거절한 비율
  return [far, frr];
}

function eer(tgt: number[], non: number[]): [number, number] {
  // FAR과 FRR이 같아지는 지점의 오류율(EER)과 그때의 문턱
  const ths = [...tgt, ...non].sort((a, b) => a - b);
  let best = 0;
  let bestGap = Infinity;
  let val = 0;
  for (const t of ths) {
    const [far, frr] = farFrr(tgt, non, t);
    if (Math.abs(far - frr) < bestGap) {
      bestGap = Math.abs(far - frr);
      best = t;
      val = (far + frr) / 2;
    }
  }
  return [val, best];
}

function quantile(a: number[], q: number): number {
  // numpy의 기본(선형 보간) 분위수
  const s = [...a].sort((x, y) => x - y);
  const pos = (s.length - 1) * q;
  const lo = Math.floor(pos);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (pos - lo);
}

const thAtFar = (non: number[], targetFar: number): number => quantile(non, 1 - targetFar); // 타인 점수의 (1 − 목표 FAR) 분위수
const thAtFrr = (tgt: number[], targetFrr: number): number => quantile(tgt, targetFrr); // 본인 점수의 (목표 FRR) 분위수
const pFalseAccept = (far: number, n: number): number => 1 - (1 - far) ** n; // n명과 차례로 비교해 '한 번이라도' 문턱을 넘을 확률 (독립 가정)

class VoiceID {
  embedFn: (y: Float32Array) => Float64Array;
  th: number;
  db: Map<string, Float64Array> = new Map(); // 이름 → 등록 템플릿 (길이 1)
  constructor(embedFn: (y: Float32Array) => Float64Array, threshold: number) {
    this.embedFn = embedFn;
    this.th = threshold;
  }
  enroll(name: string, clips: Float32Array[]): void {
    // 등록: 몇 문장의 임베딩 평균
    this.db.set(name, l2n(meanVec(clips.map((c) => l2n(this.embedFn(c))))));
  }
  verify(name: string, clip: Float32Array): [boolean, number] {
    // 1:1 본인 확인
    const t = this.db.get(name);
    if (!t) throw new Error(`등록되지 않은 사람: ${name}`);
    const s = dot(l2n(this.embedFn(clip)), t);
    return [s >= this.th, s];
  }
  identify(clip: Float32Array): [string, Record<string, number>] {
    // 1:N 누구인가 (+ 모르는 사람 거절)
    const e = l2n(this.embedFn(clip));
    const scores: Record<string, number> = {};
    for (const [n, t] of this.db) scores[n] = dot(e, t);
    const best = Object.keys(scores).reduce((a, b) => (scores[b] > scores[a] ? b : a)); // 점수(값)가 가장 큰 '이름(키)'
    return [scores[best] >= this.th ? best : "모르는 사람", scores];
  }
}

// 1) 임베딩은 길이 1 · 코사인 = 내적 · 크기와 무관
const u = [3.0, 4.0];
const nu = l2n(u);
check(Math.abs(nu[0] - 0.6) < 1e-12 && Math.abs(nu[1] - 0.8) < 1e-12 && Math.abs(dot(l2n(u), l2n(u.map((v) => 10 * v))) - 1) < 1e-12, "길이를 1로 맞추면 [3, 4] → [0.6, 0.8]이고, 크기가 달라도 같은 방향이에요.");

// 2) FAR · FRR: FAR은 타인 점수에서, FRR은 본인 점수에서 센다
const tgt = [0.9, 0.8, 0.7, 0.6];
const non = [0.5, 0.4, 0.65, 0.2];
check(farFrr(tgt, non, 0.65).join() === "0.25,0.25", "문턱 0.65: 타인 중 0.65 이상은 1/4, 본인 중 0.65 미만은 1/4이에요.");

// 3) EER: FAR = FRR인 지점 (분포가 안 겹치면 0)
check(eer([0.9, 0.8], [0.1, 0.2])[0] === 0 && Math.abs(eer(tgt, non)[0] - 0.25) < 0.13, "겹치지 않으면 EER 0, 조금 겹치면 EER이 생겨요.");

// 4) 목표 FAR에서 문턱: 타인 점수의 (1 − FAR) 분위수 → 그 문턱의 실제 FAR이 목표 근처
const r = rngOf(0);
const nonBig = Array.from({ length: 10000 }, () => 0.1 + 0.1 * r.normal());
const th = thAtFar(nonBig, 0.01);
check(Math.abs(farFrr([1.0], nonBig, th)[0] - 0.01) < 0.002, "타인 점수 위쪽 1%가 문턱 위에 있어야 해요.");
check(Math.abs(thAtFrr(Array.from({ length: 101 }, (_, i) => i / 100), 0.05) - 0.05) < 1e-9, "본인 점수 아래쪽 5% 자리가 FRR 5% 문턱이에요.");

// 5) 등록 인원이 늘면 위험 ↑: 1 − (1 − FAR)^n
check(Math.abs(pFalseAccept(0.01, 100) - 0.634) < 1e-3 && Math.abs(pFalseAccept(0.01, 1) - 0.01) < 1e-12, "FAR 1%, 100명이면 약 63%예요.");

// 6) 템플릿 보관: 암호화 → 복호화 같음 · 한 바이트 바뀌면 실패
const key = randomBytes(32);
const nonce = randomBytes(12);
const emb = Buffer.from(new Float32Array([0, 1, 2, 3]).buffer);
const c = createCipheriv("aes-256-gcm", key, nonce);
c.setAAD(Buffer.from("user"));
const blob = Buffer.concat([c.update(emb), c.final(), c.getAuthTag()]);
const open = (b: Buffer): Buffer => {
  const d = createDecipheriv("aes-256-gcm", key, nonce);
  d.setAAD(Buffer.from("user"));
  d.setAuthTag(b.subarray(b.length - 16));
  return Buffer.concat([d.update(b.subarray(0, b.length - 16)), d.final()]);
};
check(open(blob).equals(emb), "열쇠로 풀면 원래 숫자예요.");
const broken = Buffer.from(blob);
broken[broken.length - 1] ^= 1;
let failed = false;
try {
  open(broken);
} catch {
  failed = true;
}
check(failed, "한 바이트만 바뀌어도 복호화가 실패해요(변조 감지).");

// 7) 관문 순서: 목소리 → 문장 → 위조
const gate = (s: boolean, t: boolean, l: boolean): string => (!s ? "목소리" : !t ? "문장" : !l ? "위조" : "통과");
check([gate(true, true, true), gate(false, true, true), gate(true, false, true), gate(true, true, false)].join() === "통과,목소리,문장,위조", "처음 막힌 관문의 이름을 돌려줘요.");
